INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (1, 1, 1, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (1, 'he', 'קיום בחירות במועד', 'המפלגה מתחייבת לא לתמוך בהארכת כהונת הכנסת, למעט במקרה העומד בדרישות חוק היסוד: חקיקת חוק מיוחד ברוב של 80 חברי כנסת לפחות בנסיבות מיוחדות המונעות בפועל קיום בחירות במועד. ההארכה לא תעלה על הפרק הזמן הנחוץ אובייקטיבית, והחוק יקבע במקביל מועד בחירות חדש.', 'מצב מלחמה או חירום אינו אמור להעניק אוטומטית לשלטון המכהן הארכת כהונה בלתי מוגבלת.', 'עמדת המפלגה שפורסמה; הצבעות חברי הכנסת; נוסח החוק המוצע; קיומו של מועד חדש מוגדר; הנמקת חוסר האפשרות האובייקטיבית לקיים הצבעה.', 'דחייה קצרה מותרת רק כאשר באמת לא ניתן להבטיח הצבעה נגישה ובטוחה. חוסר כדאיות פוליטית, סקרים לא נוחים או עצם קיומה של פעילות צבאית אינם עילה מספקת ללא חוסר אפשרות מוכח.'),
  (1, 'ar', 'إجراء الانتخابات في موعدها', 'يلتزم الحزب بعدم دعم تمديد ولاية الكنيست، إلا في حالة تستوفي شروط القانون الأساسي: سنّ قانون خاص بأغلبية 80 نائباً على الأقل في ظروف استثنائية تمنع فعلياً إجراء الانتخابات في موعدها. لا يتجاوز التمديد المدة اللازمة موضوعياً، ويحدد القانون في الوقت نفسه موعداً جديداً للانتخابات.', 'لا ينبغي لحالة الحرب أو الطوارئ أن تمنح السلطة القائمة تلقائياً تمديداً غير محدود لولايتها.', 'موقف الحزب المنشور؛ تصويت النواب؛ نص القانون المقترح؛ وجود موعد جديد محدد؛ تبرير الاستحالة الموضوعية لإجراء التصويت.', 'يُسمح بتأجيل قصير فقط عند الاستحالة الحقيقية لضمان تصويت آمن ومتاح. عدم الملاءمة السياسية أو استطلاعات غير مواتية أو مجرد استمرار عملية عسكرية ليست أسباباً كافية دون استحالة مثبتة.'),
  (1, 'yi', 'דורכפֿירן וואַלן אין דער געשטעלטער צײַט', 'די פּאַרטיי פֿאַרפֿליכטעט זיך נישט צו שטיצן קיין פֿאַרלענגערונג פֿון דער כּנסת־קאַדענץ, אַחוץ אין אַ פֿאַל וואָס שטימט מיטן יסוד־געזעץ: אָננעמען אַ ספּעציעל געזעץ מיט אַ מערהייט פֿון נישט ווייניקער ווי 80 דעפּוטאַטן אין באַזונדערע אומשטאַנדן וואָס פֿאַרמײַדן פֿאַקטיש וואַלן אין צײַט. די פֿאַרלענגערונג טאָר נישט זײַן לענגער ווי אָביעקטיוו נייטיק, און דאָס געזעץ מוז גלײַכצײַטיק פֿעסטשטעלן אַ נײַעם וואַל־טערמין.', 'אַ מלחמה־ אָדער נויטלאַגע טאָר נישט אויטאָמאַטיש געבן דער איצטיקער מאַכט אַן אומבאַגרענעצטע פֿאַרלענגערונג.', 'די פֿאַרעפֿנטלעכטע פּאָזיציע פֿון דער פּאַרטיי; שטימונגען פֿון דעפּוטאַטן; דער טעקסט פֿונעם פֿאָרגעלייגטן געזעץ; אַ קאָנקרעטער נײַער טערמין; באַגרינדונג פֿון דער אָביעקטיווער אוממעגלעכקייט.', 'אַ קורצע אָפּלייגונג איז נאָר דערלויבט ווען מען קען טאַקע נישט זיכערשטעלן אַ צוטריטלעכע און זיכערע שטימונג. פּאָליטישע אומבאַקוועמלעכקייט אָדער אומגינציקע אַנקעטן זײַנען נישט גענוג.'),
  (1, 'ru', 'Проведение выборов в установленный срок', 'Партия обязуется не поддерживать продление срока полномочий Кнессета, кроме случая, соответствующего требованиям Основного закона: принятие специального закона большинством не менее 80 депутатов при наличии особых обстоятельств, фактически препятствующих проведению выборов в срок. Продление не должно превышать период, объективно необходимый из-за таких обстоятельств, а закон должен одновременно определить новую дату выборов.', 'Военная или чрезвычайная ситуация не должна автоматически предоставлять действующей власти неопределённое продление полномочий.', 'опубликованная позиция партии; голосования депутатов; текст предложенного закона; наличие конкретной новой даты; обоснование объективной невозможности голосования.', 'Краткий перенос допускается только при реальной невозможности обеспечить доступное и безопасное голосование. Политическая нецелесообразность, неблагоприятные опросы или сам факт продолжающейся военной операции не считаются достаточным основанием без доказанной невозможности провести выборы.'),
  (1, 'en', 'Elections held on schedule', 'The party undertakes not to support extending the Knesset''s term, except where the Basic Law''s requirements are met: a special law passed by at least 80 members under exceptional circumstances that genuinely prevent elections from being held on time. Any extension must not exceed the period objectively required, and the same law must set a new election date.', 'A war or emergency should not automatically grant the sitting government an open-ended extension of its own term.', 'the party''s published position; members'' votes; the text of the proposed law; a specific new date; justification that voting was objectively impossible.', 'A short postponement is permitted only where accessible and safe voting genuinely cannot be arranged. Political inconvenience, unfavourable polling, or the mere fact of an ongoing military operation are not sufficient grounds without demonstrated impossibility.'),
  (1, 'am', 'ምርጫ በተወሰነው ጊዜ መካሄድ', 'ፓርቲው የክኔሴትን የሥልጣን ዘመን ማራዘምን ላለመደገፍ ቃል ይገባል፤ ከመሠረታዊ ሕጉ መስፈርቶች ጋር በሚስማማ ሁኔታ ካልሆነ በስተቀር፦ ምርጫ በጊዜው እንዳይካሄድ በተጨባጭ የሚከለክሉ ልዩ ሁኔታዎች ሲኖሩ ቢያንስ በ80 እንደራሴዎች ድምፅ ልዩ ሕግ ማውጣት። ማራዘሚያው በተጨባጭ ከሚያስፈልገው ጊዜ መብለጥ የለበትም፤ ሕጉም በተመሳሳይ ጊዜ አዲስ የምርጫ ቀን መወሰን አለበት።', 'የጦርነት ወይም የአስቸኳይ ጊዜ ሁኔታ ለነባሩ ሥልጣን ያልተወሰነ የሥልጣን ማራዘሚያ በራስ-ሰር መስጠት የለበትም።', 'የፓርቲው የታተመ አቋም፤ የእንደራሴዎች ድምፅ፤ የቀረበው ሕግ ጽሑፍ፤ የተወሰነ አዲስ ቀን መኖር፤ ድምፅ መስጠት በተጨባጭ የማይቻል መሆኑ ማረጋገጫ።', 'አጭር መዘግየት የሚፈቀደው ተደራሽና ደኅንነቱ የተጠበቀ ድምፅ መስጠት በእውነት የማይቻል ሲሆን ብቻ ነው። የፖለቲካ አለመመቸት፣ የማይመቹ ሕዝብ አስተያየቶች ወይም የወታደራዊ ዘመቻ መቀጠል ብቻውን በቂ ምክንያት አይደለም።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (2, 1, 2, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (2, 'he', 'הכרה בתוצאות ובהליך החוקי', 'המפלגה מתחייבת להכיר בתוצאות שפורסמו רשמית, להשתמש רק בדרכי ערעור הקבועות בחוק, לקבל החלטות סופיות של גופי הבחירות ובתי המשפט המוסמכים, ולהבטיח העברת שלטון שקטה ובמועד.', 'מערכת הבחירות פועלת רק כאשר כל המשתתפים מקבלים הליך משותף, גם כשהתוצאה אינה נוחה להם.', 'הצהרות רשמיות; תוכן העתירות שהוגשו; פעולות לאחר פרסום התוצאות; השתתפות בהעברת הסמכויות.', 'המפלגה רשאית לערער על הפרות קונקרטיות ולדרוש ספירה חוזרת בדרך הקבועה בחוק. עד להכרעה סופית אין להשתמש במחלוקת כעילה לסירוב כללי להכיר בבחירות.'),
  (2, 'ar', 'الاعتراف بالنتائج وبالإجراءات القانونية', 'يلتزم الحزب بالاعتراف بالنتائج المنشورة رسمياً، واستخدام سبل الطعن المنصوص عليها في القانون فقط، وقبول القرارات النهائية للهيئات الانتخابية والقضائية المختصة، وضمان انتقال سلمي للسلطة في موعده.', 'لا يعمل النظام الانتخابي إلا حين يقبل جميع المشاركين إجراءً مشتركاً، بما في ذلك عند نتيجة غير مواتية لهم.', 'البيانات الرسمية؛ مضمون الشكاوى المقدمة؛ الأفعال بعد نشر النتائج؛ المشاركة في نقل الصلاحيات.', 'يحق للحزب الطعن في مخالفات محددة وطلب إعادة العد وفق القانون. وحتى صدور قرار نهائي لا يجوز استخدام النزاع ذريعة لرفض عام للاعتراف بالانتخابات.'),
  (2, 'yi', 'אָנערקענען די רעזולטאַטן און דעם געזעצלעכן פּראָצעס', 'די פּאַרטיי פֿאַרפֿליכטעט זיך אָנצוערקענען די אָפֿיציעל פֿאַרעפֿנטלעכטע רעזולטאַטן, נוצן בלויז די אין געזעץ פֿאָרגעזעענע וועגן פֿון אַפּעלירן, אָננעמען ענדגילטיקע באַשלוסן פֿון די קאָמפּעטענטע וואַל־ און געריכט־אָרגאַנען, און זיכערשטעלן אַ פֿרידלעכע און פּינקטלעכע איבערגאָב פֿון דער מאַכט.', 'דאָס וואַל־סיסטעם אַרבעט נאָר ווען אַלע באַטייליקטע נעמען אָן דעם געמיינזאַמען פּראָצעס, אויך בײַ אַן אומגינציקן רעזולטאַט.', 'אָפֿיציעלע דערקלערונגען; דער אינהאַלט פֿון די אײַנגעגעבענע קלאָגן; מעשׂים נאָך דער פֿאַרעפֿנטלעכונג פֿון די רעזולטאַטן; באַטייליקונג אין דער איבערגאָב.', 'די פּאַרטיי מעג אַפּעלירן קעגן קאָנקרעטע פֿאַרלעצונגען און פֿאָדערן איבערציילן לויטן געזעץ. ביז אַן ענדגילטיקן באַשלוס טאָר דער סיכסוך נישט דינען ווי אַ סיבה פֿאַר אַ כּלליקן אָפּזאָג אָנצוערקענען די וואַלן.'),
  (2, 'ru', 'Признание результатов и законной процедуры', 'Партия обязуется признавать официально опубликованные результаты, использовать только предусмотренные законом способы оспаривания, принимать окончательные решения компетентных избирательных и судебных органов и обеспечивать мирную и своевременную передачу власти.', 'Избирательная система работает только тогда, когда все участники принимают общую процедуру, в том числе при неблагоприятном для себя результате.', 'официальные заявления; содержание поданных жалоб; действия после публикации результатов; участие в передаче полномочий.', 'Партия вправе оспаривать конкретные нарушения и требовать пересчёта в установленном законом порядке. До принятия окончательного решения спор не должен использоваться как основание для общего отказа признавать выборы.'),
  (2, 'en', 'Accepting results and lawful procedure', 'The party undertakes to recognise officially published results, to use only the channels of challenge provided by law, to accept final decisions of the competent electoral and judicial bodies, and to ensure a peaceful and timely transfer of power.', 'An electoral system works only when every participant accepts a shared procedure, including when the outcome goes against them.', 'official statements; the content of any complaints filed; conduct after results are published; participation in the handover.', 'A party may challenge specific violations and request a recount through the process the law provides. Until a final decision, the dispute must not be used as grounds for a blanket refusal to recognise the election.'),
  (2, 'am', 'ውጤቶችንና ሕጋዊ ሂደትን መቀበል', 'ፓርቲው በይፋ የታተሙ ውጤቶችን ለመቀበል፣ በሕግ የተደነገጉ የይግባኝ መንገዶችን ብቻ ለመጠቀም፣ የብቁ የምርጫና የፍርድ አካላትን የመጨረሻ ውሳኔዎች ለመቀበል፣ እንዲሁም ሰላማዊና ወቅታዊ የሥልጣን ርክክብ ለማረጋገጥ ቃል ይገባል።', 'የምርጫ ሥርዓት የሚሠራው ሁሉም ተሳታፊዎች የጋራ ሂደቱን ሲቀበሉ ብቻ ነው፤ ውጤቱ ለእነሱ የማይመች ሲሆንም ጭምር።', 'ይፋዊ መግለጫዎች፤ የቀረቡ ቅሬታዎች ይዘት፤ ውጤቶች ከታተሙ በኋላ የተወሰዱ እርምጃዎች፤ በሥልጣን ርክክብ ላይ መሳተፍ።', 'ፓርቲው የተወሰኑ ጥሰቶችን መቃወምና በሕግ በተደነገገው መንገድ ድጋሚ ቆጠራ መጠየቅ ይችላል። የመጨረሻ ውሳኔ እስኪሰጥ ድረስ ክርክሩ ምርጫውን በጠቅላላ ላለመቀበል እንደ ምክንያት መጠቀም የለበትም።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (3, 1, 3, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (3, 'he', 'ביצוע החלטות סופיות של בית המשפט', 'המפלגה מתחייבת לא לתמוך בממשלה המכריזה שפסק דין סופי אינו מחייב, המורה לפקידים לפעול בניגוד לצו שיפוטי, או המפעילה סמכויות חירום כדי לבטל פסק דין מסוים. הממשלה רשאית לבקש הבהרה, עיון מחדש או דחייה, אך עד לשינוי ההחלטה היא פועלת לפי הצו הקיים.', 'הזכות להגנה משפטית מאבדת משמעות אם המדינה מחליטה בעצמה אילו פסקי דין לבצע.', 'תוכן החלטות הממשלה; הנחיות לגופי המדינה; מועדי ביצוע צווים שיפוטיים; פניות רשמיות לדחייה או לעיון מחדש.', 'מותרות פעולות דיוניות חוקיות שאינן מעכבות אוטומטית את ההחלטה, אלא אם בית המשפט קבע אחרת.'),
  (3, 'ar', 'تنفيذ القرارات القضائية النهائية', 'يلتزم الحزب بعدم دعم حكومة تعلن أن حكماً قضائياً نهائياً غير ملزم، أو تأمر الموظفين بالتصرف خلافاً لأمر قضائي، أو تستخدم صلاحيات الطوارئ لإلغاء حكم بعينه. للحكومة أن تطلب من المحكمة توضيحاً أو إعادة نظر أو تأجيلاً، لكنها تعمل وفق الأمر القائم إلى أن يتغير.', 'يفقد الحق في الحماية القضائية معناه إذا قررت الدولة بنفسها أي الأحكام تنفذ.', 'مضمون قرارات الحكومة؛ التعليمات للأجهزة الحكومية؛ مواعيد تنفيذ الأوامر القضائية؛ الطلبات الرسمية للتأجيل أو إعادة النظر.', 'تُقبل الإجراءات القانونية التي لا توقف القرار تلقائياً، ما لم تقرر المحكمة خلاف ذلك.'),
  (3, 'yi', 'אויספֿירן ענדגילטיקע געריכט־באַשלוסן', 'די פּאַרטיי פֿאַרפֿליכטעט זיך נישט צו שטיצן אַ רעגירונג וואָס דערקלערט אַז אַן ענדגילטיקער געריכט־באַשלוס איז נישט מחייב, וואָס באַפֿעלט באַאַמטע צו האַנדלען קעגן אַ געריכט־באַפֿעל, אָדער וואָס נוצט נויט־פֿולמאַכטן צו אַנולירן אַ קאָנקרעטן פּסק. די רעגירונג מעג בעטן אַן אויפֿקלערונג, אַ נײַע באַטראַכטונג אָדער אַן אָפּלייג, אָבער ביזן ענדערן דעם באַשלוס האַנדלט זי לויטן בֿאַשטייענדיקן באַפֿעל.', 'דאָס רעכט אויף געריכטלעכן שוץ פֿאַרלירט זײַן זין אויב די מדינה באַשליסט אַליין וועלכע פּסקים אויסצופֿירן.', 'דער אינהאַלט פֿון רעגירונג־באַשלוסן; אינסטרוקציעס צו מלוכה־אָרגאַנען; טערמינען פֿון אויספֿירן געריכט־באַפֿעלן; אָפֿיציעלע בקשות פֿאַר אָפּלייג אָדער איבערבליק.', 'דערלויבט זײַנען געזעצלעכע פּראָצעדור־מעשׂים וואָס האַלטן נישט אויטאָמאַטיש אָפּ דעם באַשלוס, סײַדן דאָס געריכט האָט אַנדערש באַשלאָסן.'),
  (3, 'ru', 'Исполнение окончательных решений суда', 'Партия обязуется не поддерживать правительство, которое заявляет о необязательности окончательного судебного решения, отдаёт чиновникам распоряжение действовать вопреки судебному приказу или применяет чрезвычайные полномочия для отмены конкретного судебного решения. Правительство вправе просить суд о разъяснении, пересмотре или отсрочке, но до изменения решения оно действует в соответствии с существующим приказом.', 'Право на судебную защиту теряет смысл, если государство самостоятельно решает, какие решения исполнять.', 'содержание решений правительства; инструкции государственным органам; сроки выполнения судебных приказов; официальные обращения за отсрочкой или пересмотром.', 'Допускаются законные процессуальные действия, не приостанавливающие решение автоматически, если суд не постановил иное.'),
  (3, 'en', 'Complying with final court rulings', 'The party undertakes not to support a government that declares a final court ruling non-binding, instructs officials to act contrary to a judicial order, or uses emergency powers to overturn a particular ruling. A government may ask the court for clarification, review or a stay, but until the ruling changes it acts in accordance with the existing order.', 'The right to judicial protection is meaningless if the state decides for itself which rulings to carry out.', 'the content of government decisions; instructions issued to state bodies; how quickly judicial orders are carried out; formal applications for a stay or review.', 'Lawful procedural steps that do not automatically suspend the ruling are permitted, unless the court has ordered otherwise.'),
  (3, 'am', 'የመጨረሻ የፍርድ ቤት ውሳኔዎችን ማስፈጸም', 'ፓርቲው የመጨረሻ የፍርድ ውሳኔ አስገዳጅ አይደለም የምትል፣ ባለሥልጣናት የፍርድ ትእዛዝን በመቃረን እንዲሠሩ የምታዝ፣ ወይም የተወሰነ ውሳኔን ለመሻር የአስቸኳይ ጊዜ ሥልጣን የምትጠቀም መንግሥትን ላለመደገፍ ቃል ይገባል። መንግሥት ማብራሪያ፣ ዳግም ግምገማ ወይም ማዘግየት መጠየቅ ይችላል፤ ውሳኔው እስኪቀየር ግን በነባሩ ትእዛዝ መሠረት ይሠራል።', 'መንግሥት የትኞቹን ውሳኔዎች እንደሚያስፈጽም ራሱ የሚወስን ከሆነ የፍርድ ጥበቃ መብት ትርጉሙን ያጣል።', 'የመንግሥት ውሳኔዎች ይዘት፤ ለመንግሥት አካላት የተሰጡ መመሪያዎች፤ የፍርድ ትእዛዞች የመፈጸሚያ ጊዜ፤ ለማዘግየት ወይም ለዳግም ግምገማ የቀረቡ ይፋዊ ጥያቄዎች።', 'ውሳኔውን በራስ-ሰር የማያቆሙ ሕጋዊ የሥነ ሥርዓት እርምጃዎች ይፈቀዳሉ፤ ፍርድ ቤቱ ሌላ ካልወሰነ በስተቀር።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (4, 1, 4, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (4, 'he', 'חשיפת קואליציות אפשריות', 'המפלגה מפרסמת לפני הבחירות: עם אילו מפלגות היא מוכנה להרכיב ממשלה; עם אילו מפלגות היא מאפשרת הסכם תמיכה מבחוץ; אילו צירופים קואליציוניים היא פוסלת; את מי היא מוכנה להמליץ להרכבת הממשלה; ואילו תנאים היא רואה כמחייבים להשתתפותה.', 'האזרח מצביע לא רק בעד מצע מפלגתי, אלא גם בעד הרכב אפשרי של הרשות המבצעת.', 'מסמך רשמי של המפלגה; ההמלצות לנשיא; המשא ומתן הקואליציוני; ההסכם הקואליציוני הסופי.', 'העמדה עשויה להשתנות בשינוי נסיבות מהותי, אך המפלגה חייבת להסביר את השינוי בפומבי, לנקוב בנסיבות החדשות, לקבל אישור של מוסד מפלגתי מוסמך ולפרסם עמדה מעודכנת לפני ההכרעה הסופית.'),
  (4, 'ar', 'الكشف عن الائتلافات الممكنة', 'ينشر الحزب قبل الانتخابات: مع أي أحزاب هو مستعد لتشكيل حكومة؛ مع أي أحزاب يقبل اتفاق دعم من الخارج؛ أي تركيبات ائتلافية يستبعدها؛ من هو مستعد لترشيحه لتشكيل الحكومة؛ وأي شروط يعتبرها ملزمة لمشاركته.', 'المواطن لا يصوّت لبرنامج حزبي فحسب، بل أيضاً لتركيبة محتملة للسلطة التنفيذية.', 'وثيقة الحزب الرسمية؛ التوصيات المقدمة للرئيس؛ المفاوضات الائتلافية؛ الاتفاق الائتلافي النهائي.', 'قد يتغير الموقف عند تغير جوهري في الظروف، لكن على الحزب أن يشرح التغيير علناً، ويسمّي الظروف الجديدة، ويحصل على موافقة هيئة حزبية مخوّلة، وينشر الموقف المحدّث قبل القرار النهائي.'),
  (4, 'yi', 'אַנטפּלעקן מעגלעכע קאָאַליציעס', 'די פּאַרטיי פֿאַרעפֿנטלעכט פֿאַר די וואַלן: מיט וועלכע פּאַרטייען זי איז גרייט צו בילדן אַ רעגירונג; מיט וועלכע זי לאָזט צו אַן אויסנווייניקן שטיצע־אָפּמאַך; וועלכע קאָאַליציע־קאָמבינאַציעס זי שליסט אויס; וועמען זי איז גרייט צו רעקאָמענדירן; און וועלכע באַדינגונגען זי האַלט פֿאַר מחייב פֿאַר איר באַטייליקונג.', 'דער בירגער שטימט נישט בלויז פֿאַר אַ פּאַרטיי־פּראָגראַם, נאָר אויך פֿאַר אַ מעגלעכן צונויפֿשטעל פֿון דער אויספֿירנדיקער מאַכט.', 'אַן אָפֿיציעל דאָקומענט פֿון דער פּאַרטיי; רעקאָמענדאַציעס צום פּרעזידענט; קאָאַליציע־פֿאַרהאַנדלונגען; דער ענדגילטיקער קאָאַליציע־אָפּמאַך.', 'די פּאָזיציע מעג זיך ענדערן בײַ אַ וועזנטלעכער ענדערונג פֿון אומשטאַנדן, אָבער די פּאַרטיי מוז עס עפֿנטלעך דערקלערן, נענען די נײַע אומשטאַנדן, באַקומען אַ הסכּמה פֿון אַ באַפֿולמעכטיקטן פּאַרטיי־אָרגאַן און פֿאַרעפֿנטלעכן די דערנײַערטע פּאָזיציע פֿאַרן ענדגילטיקן באַשלוס.'),
  (4, 'ru', 'Раскрытие возможных коалиций', 'Партия до выборов публикует: с какими партиями готова формировать правительство; с какими партиями допускает внешнее соглашение о поддержке; какие коалиционные комбинации исключает; кого готова рекомендовать для формирования правительства; какие условия считает обязательными для своего участия.', 'Гражданин голосует не только за партийную программу, но и за возможный состав исполнительной власти.', 'официальный документ партии; рекомендации президенту; коалиционные переговоры; итоговое коалиционное соглашение.', 'Позиция может измениться при существенном изменении обстоятельств, но партия должна публично объяснить изменение, назвать новые обстоятельства, получить одобрение уполномоченного партийного органа и опубликовать обновлённую позицию до принятия окончательного решения.'),
  (4, 'en', 'Disclosing possible coalitions', 'Before the election the party publishes: which parties it is prepared to form a government with; which parties it would accept an external support agreement from; which coalition combinations it rules out; whom it is prepared to recommend to form a government; and which conditions it treats as binding on its participation.', 'A citizen votes not only for a party platform but for a possible composition of the executive.', 'the party''s official document; recommendations to the President; coalition negotiations; the final coalition agreement.', 'A position may change if circumstances change materially, but the party must explain the change publicly, name the new circumstances, obtain approval from an authorised party body, and publish the updated position before any final decision.'),
  (4, 'am', 'ሊኖሩ የሚችሉ ጥምረቶችን ይፋ ማድረግ', 'ፓርቲው ከምርጫ በፊት ይፋ ያደርጋል፦ ከየትኞቹ ፓርቲዎች ጋር መንግሥት ለመመሥረት ዝግጁ እንደሆነ፤ ከየትኞቹ ጋር የውጭ ድጋፍ ስምምነት እንደሚቀበል፤ የትኞቹን የጥምረት ውህዶች እንደሚያገል፤ መንግሥት እንዲመሠርት ማንን ለመጠቆም ዝግጁ እንደሆነ፤ እና ለተሳትፎው አስገዳጅ የሚላቸውን ሁኔታዎች።', 'ዜጋው የሚመርጠው የፓርቲ ፕሮግራምን ብቻ ሳይሆን ሊኖር የሚችለውን የአስፈጻሚ አካል ስብጥርንም ጭምር ነው።', 'የፓርቲው ይፋዊ ሰነድ፤ ለፕሬዚዳንቱ የቀረቡ ምክረ ሐሳቦች፤ የጥምረት ድርድሮች፤ የመጨረሻው የጥምረት ስምምነት።', 'ሁኔታዎች በመሠረታዊ ሁኔታ ሲቀየሩ አቋም ሊለወጥ ይችላል፤ ነገር ግን ፓርቲው ለውጡን በይፋ ማብራራት፣ አዲሶቹን ሁኔታዎች መጥቀስ፣ ከተፈቀደለት የፓርቲ አካል ይሁንታ ማግኘትና የተሻሻለውን አቋም ከመጨረሻው ውሳኔ በፊት ማተም አለበት።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (5, 1, 5, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (5, 'he', 'הגבלת גודל הממשלה', 'המפלגה מתחייבת לתמוך בממשלה המונה לכל היותר 18 שרים כולל ראש הממשלה, וארבעה סגני שרים. זו מגבלה פוליטית וולונטרית. חוק היסוד הקיים מתיר מינוי שר בלי תיק ואינו קובע את המקסימום שהפרויקט מציע.', 'מספר המשרות צריך להיקבע לפי משימות הניהול, ולא לפי הצורך לחלק תפקידים סמליים.', 'הרכב הממשלה; מספר הסגנים; מבנה המשרדים שאושר; תקציבי הלשכות.', 'חריגה זמנית אפשרית רק לתקופה של עד שישה חודשים, עם נימוק מקצועי מפורסם, עם עלות מפורסמת, בתמיכת 80 חברי כנסת לפחות לפי ההצעה, ובלי יצירת מנגנון קבוע חדש עד להחלטה נפרדת. סף 70 חברי כנסת הוא תנאי פוליטי מוצע, לא דרישת חוק קיימת.'),
  (5, 'ar', 'تحديد حجم الحكومة', 'يلتزم الحزب بدعم حكومة لا تتجاوز 18 وزيراً بمن فيهم رئيس الوزراء، وأربعة نواب وزراء. هذا قيد سياسي طوعي. القانون الأساسي القائم يجيز تعيين وزير بلا حقيبة ولا يضع الحد الأقصى الذي يقترحه المشروع.', 'ينبغي أن يحدَّد عدد المناصب بمهام الإدارة، لا بالحاجة إلى توزيع مواقع رمزية.', 'تشكيلة الحكومة؛ عدد النواب؛ هيكل الوزارات المعتمد؛ ميزانيات الدواوين.', 'التجاوز المؤقت ممكن فقط لمدة لا تتعدى ستة أشهر، مع تبرير مهني منشور، وتكلفة منشورة، وبتأييد 70 نائباً على الأقل، ودون إنشاء جهاز دائم جديد إلى حين قرار منفصل. عتبة الـ70 نائباً شرط سياسي مقترح وليست مطلباً قانونياً قائماً.'),
  (5, 'yi', 'באַגרענעצן די גרייס פֿון דער רעגירונג', 'די פּאַרטיי פֿאַרפֿליכטעט זיך צו שטיצן אַ רעגירונג פֿון נישט מער ווי 18 מיניסטאָרן אַרײַנגערעכנט דעם פּרעמיער־מיניסטער, און פֿיר וויצע־מיניסטאָרן. דאָס איז אַ פֿרײַוויליקע פּאָליטישע באַגרענעצונג. דאָס איצטיקע יסוד־געזעץ דערלויבט אַ מיניסטער אָן אַ פּאָרטפֿעל און שטעלט נישט פֿעסט דעם דאָזיקן מאַקסימום.', 'די צאָל שטעלעס דאַרף באַשטימט ווערן לויט די פֿאַרוואַלטונג־אויפֿגאַבן, נישט לויטן באַדערפֿעניש צו פֿאַרטיילן סימבאָלישע פּאָסטנס.', 'דער צונויפֿשטעל פֿון דער רעגירונג; די צאָל וויצע־מיניסטאָרן; די באַשטעטיקטע סטרוקטור פֿון די מיניסטעריומס; די בודזשעטן פֿון די אַפּאַראַטן.', 'אַ צײַטווײַליקע איבערשרײַטונג איז מעגלעך נאָר אויף נישט מער ווי זעקס חדשים, מיט אַ פֿאַרעפֿנטלעכטער פּראָפֿעסיאָנעלער באַגרינדונג, מיט אַ פֿאַרעפֿנטלעכטער קאָסט, מיט דער שטיצע פֿון נישט ווייניקער ווי 70 דעפּוטאַטן, און אָן שאַפֿן אַ נײַעם שטענדיקן אַפּאַראַט. דער שוועל פֿון 70 דעפּוטאַטן איז אַ פֿאָרגעלייגטע פּאָליטישע באַדינגונג, נישט אַ בֿאַשטייענדיקע געזעץ־פֿאָדערונג.'),
  (5, 'ru', 'Ограничение размера правительства', 'Партия обязуется поддерживать правительство, состоящее не более чем из 18 министров, включая премьер-министра, и четырёх заместителей министра. Это добровольное политическое ограничение. Действующий Основной закон допускает назначение министра без портфеля и не устанавливает предлагаемого проектом максимума.', 'Количество должностей должно определяться задачами управления, а не необходимостью распределить символические посты.', 'состав правительства; число заместителей; утверждённая структура министерств; бюджет аппаратов.', 'Временное превышение возможно только на срок не более шести месяцев, при опубликованном профессиональном обосновании, при опубликованной стоимости, при поддержке не менее 70 депутатов и без создания постоянного нового аппарата до отдельного решения. Порог 70 депутатов является предлагаемым политическим условием, а не существующим требованием закона.'),
  (5, 'en', 'Capping the size of the government', 'The party undertakes to support a government of no more than 18 ministers including the Prime Minister, and four deputy ministers. This is a voluntary political limit. The Basic Law as it stands permits ministers without portfolio and sets no such maximum.', 'The number of posts should follow from the work of governing, not from a need to distribute symbolic titles.', 'the composition of the government; the number of deputies; the approved ministerial structure; the budgets of ministerial offices.', 'A temporary excess is possible only for up to six months, with published professional justification, with published cost, with the support of at least 70 members, and without creating a permanent new apparatus pending a separate decision. The 70-member threshold is a proposed political condition, not an existing requirement of law.'),
  (5, 'am', 'የመንግሥትን መጠን መገደብ', 'ፓርቲው ጠቅላይ ሚኒስትሩን ጨምሮ ከ18 ሚኒስትሮች እና ከአራት ምክትል ሚኒስትሮች የማይበልጥ መንግሥትን ለመደገፍ ቃል ይገባል። ይህ በፈቃደኝነት የተቀመጠ የፖለቲካ ገደብ ነው። ነባሩ መሠረታዊ ሕግ ያለ ሥልጣን ሚኒስትር መሾምን ይፈቅዳል፤ ይህንንም ጣሪያ አላስቀመጠም።', 'የቦታዎች ብዛት በአስተዳደር ተግባራት እንጂ ምሳሌያዊ ሹመቶችን በማከፋፈል ፍላጎት መወሰን የለበትም።', 'የመንግሥት ስብጥር፤ የምክትሎች ብዛት፤ የጸደቀው የሚኒስቴር መዋቅር፤ የጽሕፈት ቤቶች በጀት።', 'ጊዜያዊ ማለፍ የሚቻለው ከስድስት ወር ላልበለጠ ጊዜ፣ የታተመ ሙያዊ ማብራሪያ ሲኖር፣ ወጪው ሲታተም፣ ቢያንስ በ70 እንደራሴዎች ድጋፍ፣ እና እስከ ተለየ ውሳኔ ድረስ አዲስ ቋሚ መዋቅር ሳይፈጠር ብቻ ነው። የ70 እንደራሴዎች ጣሪያ የቀረበ የፖለቲካ ሁኔታ እንጂ ነባር የሕግ መስፈርት አይደለም።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (6, 1, 6, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (6, 'he', 'ויתור על שרים בלי אחריות ביצועית', 'המפלגה מתחייבת לא למנות שרים בלי תחום אחריות מוגדר, בלי סמכויות חוקיות, בלי מנגנון מדינתי אחראי ובלי יעדים ומדדי עבודה מפורסמים. מוצע לא להשתמש באפשרות החוקית למנות שרים בלי תיק.', 'לכל משרת שר צריכה להיות תפקיד ציבורי ברור.', 'לכל שר מתפרסמים: סמכויות; יחידות כפופות; תקציב; מצבת כוח אדם; יעדים לשנה.', 'מותר רכז זמני בתוך לשכת ראש הממשלה, בלי משרד נפרד, בלי תקציב קבוע נפרד ובלי כפילות סמכויות.'),
  (6, 'ar', 'التخلي عن وزراء بلا مسؤولية تنفيذية', 'يلتزم الحزب بعدم تعيين وزراء بلا مجال مسؤولية محدد، وبلا صلاحيات قانونية، وبلا جهاز حكومي مساءل، وبلا أهداف ومؤشرات عمل منشورة. ويُقترح عدم استخدام الإمكانية القانونية لتعيين وزراء بلا حقيبة.', 'لكل منصب وزاري يجب أن تكون وظيفة عامة واضحة.', 'يُنشر لكل وزير: الصلاحيات؛ الوحدات التابعة؛ الميزانية؛ عدد الموظفين؛ أهداف السنة.', 'يُسمح بمنسق مؤقت داخل ديوان رئيس الوزراء، دون وزارة منفصلة ودون ميزانية دائمة منفصلة ودون ازدواج الصلاحيات.'),
  (6, 'yi', 'אָפּזאָג פֿון מיניסטאָרן אָן אָפּעראַטיווער אחריות', 'די פּאַרטיי פֿאַרפֿליכטעט זיך נישט צו באַשטימען מיניסטאָרן אָן אַ באַשטימטן פֿאַראַנטוואָרטלעכקייט־געביט, אָן געזעצלעכע פֿולמאַכטן, אָן אַ פֿאַראַנטוואָרטלעכן מלוכה־אַפּאַראַט און אָן פֿאַרעפֿנטלעכטע צילן און אַרבעט־מאָסן. עס ווערט פֿאָרגעלייגט נישט צו נוצן די געזעצלעכע מעגלעכקייט צו באַשטימען מיניסטאָרן אָן פּאָרטפֿעל.', 'יעדע מיניסטער־שטעלע דאַרף האָבן אַ קלאָרע עפֿנטלעכע פֿונקציע.', 'פֿאַר יעדן מיניסטער ווערן פֿאַרעפֿנטלעכט: פֿולמאַכטן; אונטערגעאָרדנטע אָפּטיילן; בודזשעט; צאָל אָנגעשטעלטע; צילן פֿאַרן יאָר.', 'דערלויבט איז אַ צײַטווײַליקער קאָאָרדינאַטאָר אין דעם אַפּאַראַט פֿונעם פּרעמיער, אָן אַ באַזונדער מיניסטעריום, אָן אַ באַזונדערן שטענדיקן בודזשעט און אָן דופּליקירן פֿולמאַכטן.'),
  (6, 'ru', 'Отказ от министров без операционной ответственности', 'Партия обязуется не назначать министров без определённой сферы ответственности, без законных полномочий, без подотчётного государственного аппарата и без опубликованных целей и показателей работы. Предлагается не использовать предусмотренную законом возможность назначения министров без портфеля.', 'Каждая министерская должность должна иметь понятную общественную функцию.', 'Для каждого министра публикуются: полномочия; подчинённые подразделения; бюджет; численность аппарата; цели на год.', 'Допускается временный координатор внутри аппарата премьер-министра без отдельного министерства, отдельного постоянного бюджета и дублирования полномочий.'),
  (6, 'en', 'No ministers without operational responsibility', 'The party undertakes not to appoint ministers without a defined area of responsibility, lawful powers, an accountable state apparatus, and published objectives and performance measures. It is proposed not to use the statutory option of appointing ministers without portfolio.', 'Every ministerial post should have a public function that can be stated plainly.', 'for each minister the following are published: powers; subordinate units; budget; staff numbers; objectives for the year.', 'A temporary coordinator inside the Prime Minister''s Office is permitted, without a separate ministry, without a separate standing budget, and without duplicating powers.'),
  (6, 'am', 'የተግባር ኃላፊነት የሌላቸው ሚኒስትሮችን አለመሾም', 'ፓርቲው የተወሰነ የኃላፊነት መስክ፣ ሕጋዊ ሥልጣን፣ ተጠያቂ የመንግሥት መዋቅር እና የታተሙ ግቦችና የሥራ መለኪያዎች ሳይኖሩ ሚኒስትሮችን ላለመሾም ቃል ይገባል። ያለ ሥልጣን ሚኒስትር የመሾም ሕጋዊ አማራጭን ላለመጠቀም ይመከራል።', 'እያንዳንዱ የሚኒስትር ቦታ ግልጽ የሆነ የሕዝብ ተግባር ሊኖረው ይገባል።', 'ለእያንዳንዱ ሚኒስትር ይታተማል፦ ሥልጣን፤ የበታች ክፍሎች፤ በጀት፤ የሠራተኞች ብዛት፤ የዓመቱ ግቦች።', 'በጠቅላይ ሚኒስትሩ ጽሕፈት ቤት ውስጥ ጊዜያዊ አስተባባሪ ይፈቀዳል፤ የተለየ ሚኒስቴር፣ የተለየ ቋሚ በጀት እና የሥልጣን ድግግሞሽ ሳይኖር።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (7, 1, 7, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (7, 'he', 'תוכנית 100 הימים הראשונים', 'המפלגה מפרסמת לפני הבחירות רשימת פעולות שתקדם ב-100 הימים הראשונים להשתתפותה בממשלה. לכל פעולה מצוינים: ההחלטה; המועד; הגוף האחראי; החקיקה הנדרשת; ההשלכות התקציביות הידועות; קריטריון הביצוע.', 'הצהרה כללית אינה מאפשרת להעריך את מוכנות המפלגה לנהל.', 'לאחר הרכבת הממשלה מתפרסם מעקב פתוח עם הסטטוסים: לא התחיל; בעבודה; בוצע; שונה; נדחה עם הסבר.', 'המועד ניתן לשינוי עקב מכשול אובייקטיבי. יש לפרסם את הסיבה, את המועד החדש ואת הגוף האחראי.'),
  (7, 'ar', 'برنامج المئة يوم الأولى', 'ينشر الحزب قبل الانتخابات قائمة إجراءات سيدفع بها في أول 100 يوم من مشاركته في الحكومة. ولكل إجراء يُذكر: القرار؛ الموعد؛ الجهة المسؤولة؛ التشريع اللازم؛ الآثار الميزانية المعروفة؛ معيار التنفيذ.', 'الإعلان العام لا يتيح تقييم جاهزية الحزب للحكم.', 'بعد تشكيل الحكومة يُنشر متتبع مفتوح بالحالات: لم يبدأ؛ قيد العمل؛ نُفذ؛ عُدل؛ أُجل مع تفسير.', 'يمكن تغيير الموعد بسبب عائق موضوعي. ويجب نشر السبب والموعد الجديد والجهة المسؤولة.'),
  (7, 'yi', 'פּראָגראַם פֿון די ערשטע 100 טעג', 'די פּאַרטיי פֿאַרעפֿנטלעכט פֿאַר די וואַלן אַ רשימה פֿון מעשׂים וואָס זי וועט פֿירן אין די ערשטע 100 טעג פֿון איר באַטייליקונג אין דער רעגירונג. פֿאַר יעדער מעשׂה ווערן אָנגעוויזן: דער באַשלוס; דער טערמין; דער פֿאַראַנטוואָרטלעכער אָרגאַן; די נייטיקע געזעצגעבונג; די באַוווּסטע בודזשעט־פֿאָלגן; דער אויספֿיר־קריטעריום.', 'אַ כּלליקע דעקלאַראַציע לאָזט נישט אָפּשאַצן די גרייטקייט פֿון דער פּאַרטיי צו רעגירן.', 'נאָך דער בילדונג פֿון דער רעגירונג ווערט פֿאַרעפֿנטלעכט אַן אָפֿענער טרעקער מיט די סטאַטוסן: נישט אָנגעהויבן; אין אַרבעט; אויסגעפֿירט; געענדערט; אָפּגעלייגט מיט אַן דערקלערונג.', 'דער טערמין מעג געענדערט ווערן צוליב אַן אָביעקטיוון מניעה. מען מוז פֿאַרעפֿנטלעכן די סיבה, דעם נײַעם טערמין און דעם פֿאַראַנטוואָרטלעכן אָרגאַן.'),
  (7, 'ru', 'Программа первых 100 дней', 'Партия публикует до выборов перечень действий, которые она будет продвигать в первые 100 дней участия в правительстве. Для каждого действия указываются: решение; срок; ответственный орган; необходимое законодательство; известные бюджетные последствия; критерий выполнения.', 'Общая декларация не позволяет оценить готовность партии к управлению.', 'После формирования правительства публикуется открытый трекер со статусами: не начато; в работе; выполнено; изменено; отложено с объяснением.', 'Срок может быть изменён из-за объективного препятствия. Должны быть опубликованы причина, новый срок и ответственный орган.'),
  (7, 'en', 'A first-100-days programme', 'Before the election the party publishes the actions it will pursue in its first 100 days in government. For each action it states: the decision; the deadline; the responsible body; the legislation required; the known budgetary consequences; and the criterion for completion.', 'A general declaration gives no way to judge whether a party is ready to govern.', 'once a government is formed, an open tracker is published with statuses: not started; in progress; done; changed; postponed with an explanation.', 'A deadline may change because of an objective obstacle. The reason, the new deadline and the responsible body must be published.'),
  (7, 'am', 'የመጀመሪያዎቹ 100 ቀናት ፕሮግራም', 'ፓርቲው በመንግሥት ውስጥ በሚሳተፍበት የመጀመሪያዎቹ 100 ቀናት የሚያራምዳቸውን እርምጃዎች ዝርዝር ከምርጫ በፊት ያትማል። ለእያንዳንዱ እርምጃ ይገለጻል፦ ውሳኔው፤ የጊዜ ገደቡ፤ ኃላፊው አካል፤ የሚያስፈልገው ሕግ፤ የሚታወቁ የበጀት ውጤቶች፤ የመፈጸሚያ መስፈርት።', 'አጠቃላይ መግለጫ የፓርቲውን የመግዛት ዝግጁነት ለመገምገም አያስችልም።', 'መንግሥት ከተመሠረተ በኋላ ክፍት መከታተያ ይታተማል፦ አልተጀመረም፤ በሂደት ላይ፤ ተፈጽሟል፤ ተቀይሯል፤ በማብራሪያ ተላልፏል።', 'በተጨባጭ እንቅፋት ምክንያት የጊዜ ገደብ ሊቀየር ይችላል። ምክንያቱ፣ አዲሱ የጊዜ ገደብ እና ኃላፊው አካል መታተም አለባቸው።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (8, 1, 8, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (8, 'he', 'ועדת חקירה ממלכתית לאירועי 7 באוקטובר', 'המפלגה מתחייבת לתמוך בהחלטת ממשלה על הקמת ועדת חקירה ממלכתית לפי חוק ועדות חקירה. לפי המנגנון הקיים הממשלה מחליטה על הקמת הוועדה וקובעת את נושא החקירה, ולאחר מכן נשיא בית המשפט העליון ממנה את היושב ראש ואת יתר החברים. מוצע שההחלטה תתקבל לא יאוחר מ-14 יום לאחר הרכבת הממשלה.', 'החקירה צריכה לכלול את הגורמים האישיים והמערכתיים לכישלון, בלי להוציא מראש דרגים שלמים.', 'החלטת הממשלה; המנדט שהוגדר רשמית; פרסום המינוי; הסמכויות והמשאבים שהוענקו לוועדה.', 'חומר מסווג נדון במסגרת מוגנת הקבועה בחוק. אין להשתמש בסיווג כדי להוציא קטגוריה שלמה של החלטות מן החקירה.'),
  (8, 'ar', 'لجنة تحقيق رسمية في أحداث السابع من أكتوبر', 'يلتزم الحزب بدعم قرار حكومي بتشكيل لجنة تحقيق رسمية وفق قانون لجان التحقيق. وبحسب الآلية القائمة تقرر الحكومة تشكيل اللجنة وتحدد موضوع التحقيق، ثم يعيّن رئيس المحكمة العليا رئيس اللجنة وبقية أعضائها. ويُقترح أن يُتخذ القرار في موعد لا يتجاوز 14 يوماً من تشكيل الحكومة.', 'ينبغي أن يشمل التحقيق الأسباب الشخصية والبنيوية للإخفاق، دون استثناء مستويات كاملة سلفاً.', 'قرار الحكومة؛ التفويض المحدد رسمياً؛ نشر التعيين؛ الصلاحيات والموارد الممنوحة للجنة.', 'تُدرس المواد السرية في إطار محمي ينص عليه القانون. ولا يجوز استخدام السرية لاستثناء فئة كاملة من القرارات من التحقيق.'),
  (8, 'yi', 'אַ מלוכהשע אויספֿאָרשונג־קאָמיסיע וועגן די געשעענישן פֿון 7טן אָקטאָבער', 'די פּאַרטיי פֿאַרפֿליכטעט זיך צו שטיצן אַ רעגירונג־באַשלוס וועגן שאַפֿן אַ מלוכהשע אויספֿאָרשונג־קאָמיסיע לויטן געזעץ וועגן אויספֿאָרשונג־קאָמיסיעס. לויטן איצטיקן מעכאַניזם באַשליסט די רעגירונג וועגן שאַפֿן די קאָמיסיע און באַשטימט דעם געגנשטאַנד פֿון דער אויספֿאָרשונג, און דערנאָך באַשטימט דער פּרעזידענט פֿונעם העכסטן געריכט דעם פֿאָרזיצער און די איבעריקע מיטגלידער. עס ווערט פֿאָרגעלייגט אַז דער באַשלוס זאָל אָנגענומען ווערן נישט שפּעטער ווי 14 טעג נאָך דער בילדונג פֿון דער רעגירונג.', 'די אויספֿאָרשונג דאַרף אַרומנעמען די פּערזענלעכע און סיסטעמישע סיבות פֿונעם דורכפֿאַל, אָן אויסשליסן פֿון פֿאָרויס גאַנצע מדרגות פֿון דער מאַכט.', 'דער רעגירונג־באַשלוס; דער אָפֿיציעל באַשטימטער מאַנדאַט; די פֿאַרעפֿנטלעכונג פֿון דער באַשטימונג; די פֿולמאַכטן און מיטלען געגעבן דער קאָמיסיע.', 'געהיימע מאַטעריאַלן ווערן באַהאַנדלט אין דעם אין געזעץ פֿאָרגעזעענעם באַשיצטן רעזשים. געהיימקייט טאָר נישט גענוצט ווערן צו אויסשליסן אַ גאַנצע קאַטעגאָריע באַשלוסן.'),
  (8, 'ru', 'Государственная комиссия расследования событий 7 октября', 'Партия обязуется поддержать решение правительства о создании государственной комиссии расследования в соответствии с Законом о комиссиях расследования. По действующему механизму правительство принимает решение о создании комиссии и определяет предмет расследования, после чего председатель Верховного суда назначает председателя и остальных членов комиссии. Предлагаемый срок: решение правительства принимается не позднее 14 дней после его формирования.', 'Расследование должно охватывать персональные и системные причины провала, не исключая заранее отдельные уровни власти.', 'решение правительства; официально определённый мандат; публикация назначения; предоставленные комиссии полномочия и ресурсы. Минимальный предмет: политический уровень; армия и военная разведка; ШАБАК и другие разведывательные системы; полиция; гражданская оборона и готовность тыла; процессы обмена информацией; подготовка к угрозе; принятие решений после начала нападения.', 'Секретные материалы рассматриваются в предусмотренном законом защищённом режиме. Секретность не должна использоваться для исключения целой категории решений из расследования.'),
  (8, 'en', 'A state commission of inquiry into 7 October', 'The party undertakes to support a government decision to establish a state commission of inquiry under the Commissions of Inquiry Law. Under the existing mechanism the government decides to establish the commission and defines its subject matter, after which the President of the Supreme Court appoints the chair and remaining members. The proposed deadline is a government decision no later than 14 days after the government is formed.', 'An inquiry must cover both the personal and the systemic causes of the failure, without excluding entire levels of authority in advance.', 'the government decision; the formally defined mandate; publication of the appointments; the powers and resources given to the commission. The minimum subject matter: the political level; the army and military intelligence; the Shin Bet and other intelligence services; the police; civil defence and home-front readiness; information-sharing processes; preparation for the threat; decision-making after the attack began.', 'Classified material is handled under the protected regime the law provides. Classification must not be used to exclude an entire category of decisions from the inquiry.'),
  (8, 'am', 'የጥቅምት 7 ክስተቶች የመንግሥት የምርመራ ኮሚሽን', 'ፓርቲው በምርመራ ኮሚሽኖች ሕግ መሠረት የመንግሥት የምርመራ ኮሚሽን እንዲቋቋም የሚደረገውን የመንግሥት ውሳኔ ለመደገፍ ቃል ይገባል። በነባሩ አሠራር መንግሥት ኮሚሽኑን ስለማቋቋም ወስኖ የምርመራውን ጉዳይ ይወስናል፤ ከዚያም የጠቅላይ ፍርድ ቤት ፕሬዚዳንት ሊቀመንበሩንና ሌሎቹን አባላት ይሾማል። የቀረበው የጊዜ ገደብ፦ መንግሥት ከተመሠረተ በኋላ ከ14 ቀናት ባልበለጠ ጊዜ ውሳኔ መሰጠት አለበት።', 'ምርመራው የውድቀቱን ግላዊና ሥርዓታዊ ምክንያቶች መሸፈን አለበት፤ ሙሉ የሥልጣን እርከኖችን አስቀድሞ ሳያገል።', 'የመንግሥት ውሳኔ፤ በይፋ የተወሰነ ሥልጣን፤ የሹመቱ ማተም፤ ለኮሚሽኑ የተሰጡ ሥልጣንና ሀብቶች።', 'ሚስጥራዊ ሰነዶች በሕግ በተደነገገው የተጠበቀ ሥርዓት ይታያሉ። ሚስጥራዊነት ሙሉ የውሳኔ ምድብን ከምርመራ ለማግለል መጠቀም የለበትም።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (9, 1, 9, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (9, 'he', 'שימוש לא מפלגתי במשטרה, בצבא ובשירותי הביטחון', 'המפלגה מכירה בשליטה האזרחית החוקית של הממשלה הנבחרת על מערכת הביטחון, ובמקביל מתחייבת: לא להשתמש בגופי הביטחון לתעמולה מפלגתית; לא להתערב בחקירות פליליות מסוימות מעבר לגבולות החוק; לא להנחות כיצד תתייחס המשטרה למחאה או לקבוצה פוליטית מסוימת; לא להתנות קידום קצינים בנאמנות מפלגתית; לבצע מינויי בכירים לפי קריטריונים מקצועיים מפורסמים; לתעד הנחיות מדיניות כלליות; לשמר את ההערכה המקצועית של הפיקוד וגופי המודיעין.', 'עצמאות מקצועית אינה מבטלת פיקוח דמוקרטי, אך גופי הביטחון אינם אמורים להפוך לכלי של פוליטיקאי או מפלגה מסוימת.', 'הנחיות רשמיות; הליך המינויים; מסקנות ועדות; התערבות בתיקים מסוימים; החלטות בית המשפט והגופים המשפטיים.', 'הממשלה והשרים המוסמכים שומרים על כל הסמכויות האסטרטגיות, התקציביות והאישיות שהוענקו להם בחוק.'),
  (9, 'ar', 'استخدام غير حزبي للشرطة والجيش وأجهزة الأمن', 'يعترف الحزب بالرقابة المدنية القانونية للحكومة المنتخبة على المنظومة الأمنية، ويلتزم في الوقت نفسه: بعدم استخدام الأجهزة الأمنية للدعاية الحزبية؛ وعدم التدخل في تحقيقات جنائية بعينها خارج حدود القانون؛ وعدم إعطاء تعليمات بشأن تعامل الشرطة مع احتجاج أو مجموعة سياسية بعينها؛ وعدم ربط ترقية الضباط بالولاء الحزبي؛ وإجراء تعيينات القيادات وفق معايير مهنية منشورة؛ وتوثيق التوجيهات السياسية العامة؛ والحفاظ على التقدير المهني للقيادة وأجهزة الاستخبارات.', 'الاستقلال المهني لا يلغي الرقابة الديمقراطية، لكن الأجهزة الأمنية يجب ألا تتحول إلى أداة بيد سياسي أو حزب بعينه.', 'التوجيهات الرسمية؛ إجراءات التعيين؛ استنتاجات اللجان؛ التدخل في قضايا بعينها؛ قرارات المحاكم والجهات القانونية.', 'تحتفظ الحكومة والوزراء المخوّلون بكل الصلاحيات الاستراتيجية والميزانية والوظيفية التي يمنحها لهم القانون.'),
  (9, 'yi', 'נישט־פּאַרטייאישער נוץ פֿון פּאָליציי, אַרמיי און זיכערהייט־דינסטן', 'די פּאַרטיי דערקענט אָן די געזעצלעכע ציווילע קאָנטראָל פֿון דער דערוויילטער רעגירונג איבערן זיכערהייט־סיסטעם, און פֿאַרפֿליכטעט זיך גלײַכצײַטיק: נישט צו נוצן די זיכערהייט־אָרגאַנען פֿאַר פּאַרטיי־פּראָפּאַגאַנדע; נישט אַרײַנצומישן זיך אין קאָנקרעטע קרימינעלע אויספֿאָרשונגען אַחוץ אין די גרענעצן פֿון געזעץ; נישט צו געבן אָנווײַזונגען וועגן פּאָליציי־באַציִונג צו אַ קאָנקרעטן פּראָטעסט אָדער אַ פּאָליטישער גרופּע; נישט צו מאַכן אָפֿיציר־פֿאַרערונג אָפּהענגיק פֿון פּאַרטיי־געטרײַשאַפֿט; דורכצופֿירן באַשטימונגען לויט פֿאַרעפֿנטלעכטע פּראָפֿעסיאָנעלע קריטעריעס.', 'פּראָפֿעסיאָנעלע זעלבשטענדיקייט אַנולירט נישט די דעמאָקראַטישע קאָנטראָל, אָבער די זיכערהייט־אָרגאַנען טאָרן נישט ווערן אַ געצײַג פֿון אַ קאָנקרעטן פּאָליטיקער אָדער אַ פּאַרטיי.', 'אָפֿיציעלע דירעקטיוון; די פּראָצעדור פֿון באַשטימונגען; מסקנות פֿון קאָמיסיעס; אַרײַנמישונג אין קאָנקרעטע פֿאַלן; באַשלוסן פֿון געריכט און יוריסטישע אָרגאַנען.', 'די רעגירונג און די באַפֿולמעכטיקטע מיניסטאָרן היטן אַלע סטראַטעגישע, בודזשעט־ און קאַדער־פֿולמאַכטן וואָס דער געזעץ גיט זיי.'),
  (9, 'ru', 'Непартийное использование полиции, армии и спецслужб', 'Партия признаёт законный гражданский контроль избранного правительства над системой безопасности и одновременно обязуется: не использовать силовые органы для партийной агитации; не вмешиваться в конкретные уголовные расследования иначе чем в пределах закона; не давать указания о полицейском отношении к конкретному протесту или политической группе; не ставить продвижение офицеров в зависимость от партийной лояльности; проводить назначения руководителей по опубликованным профессиональным критериям; документировать общие политические директивы; сохранять профессиональную оценку командования и разведывательных органов.', 'Профессиональная самостоятельность не отменяет демократический контроль, но силовые органы не должны превращаться в инструмент конкретного политика или партии.', 'официальные директивы; процедура назначений; заключения комиссий; вмешательство в конкретные дела; решения суда и юридических органов.', 'Правительство и уполномоченные министры сохраняют все стратегические, бюджетные и кадровые полномочия, предоставленные им законом.'),
  (9, 'en', 'Non-partisan use of the police, army and security services', 'The party recognises the elected government''s lawful civilian control of the security system, and at the same time undertakes: not to use security bodies for party campaigning; not to interfere in particular criminal investigations other than within the law; not to direct how the police treat a particular protest or political group; not to make officers'' promotion depend on party loyalty; to make senior appointments against published professional criteria; to document general policy directives; and to preserve the professional judgement of the command and intelligence bodies.', 'Professional independence does not cancel democratic oversight, but security bodies must not become the instrument of a particular politician or party.', 'official directives; the appointments procedure; commission findings; interference in particular cases; rulings of the courts and legal authorities.', 'The government and authorised ministers retain every strategic, budgetary and personnel power the law grants them.'),
  (9, 'am', 'ፖሊስን፣ ሠራዊትንና የደኅንነት አገልግሎቶችን ከፓርቲ ወገንተኝነት ነጻ ማድረግ', 'ፓርቲው የተመረጠው መንግሥት በደኅንነት ሥርዓቱ ላይ ያለውን ሕጋዊ ሲቪል ቁጥጥር ይቀበላል፤ በተመሳሳይም ቃል ይገባል፦ የደኅንነት አካላትን ለፓርቲ ቅስቀሳ ላለመጠቀም፤ በተወሰኑ የወንጀል ምርመራዎች ከሕግ ውጪ ጣልቃ ላለመግባት፤ ፖሊስ ለተወሰነ ተቃውሞ ወይም የፖለቲካ ቡድን ስለሚኖረው አያያዝ መመሪያ ላለመስጠት፤ የመኮንኖችን ዕድገት በፓርቲ ታማኝነት ላይ ላለመመሥረት፤ የአመራር ሹመቶችን በታተሙ ሙያዊ መስፈርቶች ለማካሄድ።', 'ሙያዊ ነጻነት ዴሞክራሲያዊ ቁጥጥርን አይሽርም፤ ነገር ግን የደኅንነት አካላት የአንድ ፖለቲከኛ ወይም ፓርቲ መሣሪያ መሆን የለባቸውም።', 'ይፋዊ መመሪያዎች፤ የሹመት ሂደት፤ የኮሚሽኖች ውሳኔዎች፤ በተወሰኑ ጉዳዮች ላይ ጣልቃ መግባት፤ የፍርድ ቤትና የሕግ አካላት ውሳኔዎች።', 'መንግሥትና የተፈቀደላቸው ሚኒስትሮች በሕግ የተሰጣቸውን ሁሉንም ስትራቴጂያዊ፣ የበጀትና የሠራተኛ ሥልጣኖች ይይዛሉ።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (10, 1, 10, 1, 'standard');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (10, 'he', 'פומביות ההתחייבויות הקואליציוניות והתקציביות', 'המפלגה מתחייבת לפרסם: הסכמים קואליציוניים; נספחים; התחייבויות לתפקידים; הקצאות תקציביות נוספות; קריטריונים לחלוקת כספים; מקורות המימון המשוערים.', 'הבוחר צריך להבין לא רק את הרכב הקואליציה, אלא גם את מחיר ההסכמים שנחתמו.', 'ההסכמים שפורסמו; תקציב המדינה; החלטות ועדות הכספים; העברות תקציביות.', 'אפשר לא לפרסם באופן זמני רק מידע שחשיפתו יוצרת סיכון ביטחוני קונקרטי או פוגעת במידע פרטי המוגן בחוק. יש לציין את הנימוק.'),
  (10, 'ar', 'علانية الالتزامات الائتلافية والميزانية', 'يلتزم الحزب بنشر: الاتفاقات الائتلافية؛ الملاحق؛ الالتزامات بشأن المناصب؛ المخصصات الميزانية الإضافية؛ معايير توزيع الأموال؛ مصادر التمويل المفترضة.', 'على الناخب أن يفهم لا تركيبة الائتلاف فحسب، بل أيضاً ثمن الاتفاقات المبرمة.', 'الاتفاقات المنشورة؛ ميزانية الدولة؛ قرارات لجان المالية؛ التحويلات الميزانية.', 'لا يجوز حجب النشر مؤقتاً إلا عن معلومات يخلق كشفها خطراً أمنياً محدداً أو ينتهك معلومات خاصة يحميها القانون. ويجب ذكر السبب.'),
  (10, 'yi', 'עפֿנטלעכקייט פֿון קאָאַליציע־ און בודזשעט־פֿאַרפֿליכטונגען', 'די פּאַרטיי פֿאַרפֿליכטעט זיך צו פֿאַרעפֿנטלעכן: קאָאַליציע־אָפּמאַכן; בײַלאַגעס; פֿאַרפֿליכטונגען וועגן שטעלעס; צוגאָב־בודזשעט־אַסיגנאַציעס; קריטעריעס פֿון פֿאַרטיילן געלטער; די משוערדיקע קוואַלן פֿון פֿינאַנצירונג.', 'דער וויילער דאַרף פֿאַרשטיין נישט בלויז דעם צונויפֿשטעל פֿון דער קאָאַליציע, נאָר אויך דעם פּרײַז פֿון די געשלאָסענע אָפּמאַכן.', 'די פֿאַרעפֿנטלעכטע אָפּמאַכן; דער מלוכה־בודזשעט; באַשלוסן פֿון די פֿינאַנץ־קאָמיטעטן; בודזשעט־איבערפֿירן.', 'צײַטווײַליק מעג נישט פֿאַרעפֿנטלעכט ווערן בלויז אינפֿאָרמאַציע וועמענס אַנטפּלעקונג שאַפֿט אַ קאָנקרעטן זיכערהייט־ריזיקאָ אָדער פֿאַרלעצט אין געזעץ באַשיצטע פּריוואַטע אינפֿאָרמאַציע. די סיבה מוז אָנגעוויזן ווערן.'),
  (10, 'ru', 'Публичность коалиционных и бюджетных обязательств', 'Партия обязуется публиковать: коалиционные соглашения; приложения; обязательства о должностях; дополнительные бюджетные ассигнования; критерии распределения средств; предполагаемые источники финансирования.', 'Избиратель должен понимать не только состав коалиции, но и цену заключённых соглашений.', 'опубликованные соглашения; государственный бюджет; решения финансовых комитетов; бюджетные переводы.', 'Временно может не публиковаться только информация, раскрытие которой создаёт конкретный риск безопасности или нарушает защищённую законом частную информацию. Основание должно быть указано.'),
  (10, 'en', 'Publishing coalition and budget commitments', 'The party undertakes to publish: coalition agreements; annexes; commitments regarding posts; additional budget allocations; the criteria for distributing funds; and the expected sources of funding.', 'A voter needs to understand not only who is in the coalition but what the agreements cost.', 'the published agreements; the state budget; decisions of the finance committees; budget transfers.', 'Publication may be withheld temporarily only for information whose disclosure creates a specific security risk or breaches private information protected by law. The grounds must be stated.'),
  (10, 'am', 'የጥምረትና የበጀት ቁርጠኝነቶች ይፋዊነት', 'ፓርቲው ለማተም ቃል ይገባል፦ የጥምረት ስምምነቶች፤ አባሪዎች፤ ስለ ቦታዎች የተገቡ ቃሎች፤ ተጨማሪ የበጀት ድልድሎች፤ የገንዘብ ክፍፍል መስፈርቶች፤ የሚጠበቁ የገንዘብ ምንጮች።', 'መራጩ የጥምረቱን ስብጥር ብቻ ሳይሆን የተደረሱ ስምምነቶችን ዋጋም መረዳት አለበት።', 'የታተሙ ስምምነቶች፤ የመንግሥት በጀት፤ የገንዘብ ኮሚቴዎች ውሳኔዎች፤ የበጀት ዝውውሮች።', 'በጊዜያዊነት ሊታተም የማይችለው ይፋ መደረጉ የተወሰነ የደኅንነት ስጋት የሚፈጥር ወይም በሕግ የተጠበቀ የግል መረጃን የሚጥስ መረጃ ብቻ ነው። ምክንያቱ መገለጽ አለበት።');
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (11, 1, 1, 1, 'coalition');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (11, 'he', 'מנגנון מועמד משותף', 'החותמים בוחרים ומפרסמים לפני הבחירות מנגנון אחד: ראש המפלגה החותמת בעלת מספר המנדטים הגדול ביותר; מועמד שהוסכם מראש; המועמד שקיבל את מספר ההמלצות המחייבות הגדול ביותר; או נוסחה אחרת שפורסמה מראש. המנגנון חייב לכלול הליך להחלפת מועמד במקרה של מניעה משפטית, ויתור מרצון, פטירה או מחלה קשה.', NULL, NULL, NULL),
  (11, 'ar', 'آلية المرشح المشترك', 'يختار الموقّعون وينشرون قبل الانتخابات آلية واحدة: رئيس الحزب الموقّع الحائز أكبر عدد من المقاعد؛ أو مرشح متفق عليه مسبقاً؛ أو المرشح الذي نال أكبر عدد من التوصيات الملزمة؛ أو صيغة أخرى منشورة سلفاً. ويجب أن تتضمن الآلية إجراءً لاستبدال المرشح عند الاستحالة القانونية أو التنازل الطوعي أو الوفاة أو المرض الشديد.', NULL, NULL, NULL),
  (11, 'yi', 'אַ געמיינזאַמער קאַנדידאַט־מעכאַניזם', 'די אונטערשרײַבער קלײַבן אויס און פֿאַרעפֿנטלעכן פֿאַר די וואַלן איין מעכאַניזם: דער פֿירער פֿון דער אונטערגעשריבענער פּאַרטיי מיט די מערסטע מאַנדאַטן; אַ פֿריִער אָפּגערעדטער קאַנדידאַט; דער קאַנדידאַט וואָס האָט באַקומען די מערסטע מחייבֿדיקע רעקאָמענדאַציעס; אָדער אַן אַנדער פֿריִער פֿאַרעפֿנטלעכטע פֿאָרמולע. דער מעכאַניזם מוז אַנטהאַלטן אַ פּראָצעדור פֿאַרן בײַטן דעם קאַנדידאַט בײַ אַ יוריסטישער אוממעגלעכקייט, אַ פֿרײַוויליקן אָפּזאָג, אַ פּטירה אָדער אַ שווערער קרענק.', NULL, NULL, NULL),
  (11, 'ru', 'Общий механизм кандидата', 'Подписанты до выборов выбирают и публикуют один механизм: лидер подписавшей партии с наибольшим числом мандатов; заранее согласованный кандидат; кандидат, получивший наибольшее число обязательных рекомендаций подписантов; иная заранее опубликованная формула. Механизм должен содержать процедуру замены кандидата при юридической невозможности, добровольном отказе, смерти или тяжёлой болезни.', NULL, NULL, NULL),
  (11, 'en', 'A shared candidate mechanism', 'Before the election the signatories choose and publish one mechanism: the leader of the signatory party with the most seats; a candidate agreed in advance; the candidate receiving the most binding recommendations from signatories; or another formula published in advance. The mechanism must include a procedure for replacing the candidate in the event of legal impossibility, voluntary withdrawal, death or serious illness.', NULL, NULL, NULL),
  (11, 'am', 'የጋራ የእጩ አሠራር', 'ፈራሚዎቹ ከምርጫ በፊት አንድ አሠራር መርጠው ያትማሉ፦ ከፈረሙት ፓርቲዎች ከፍተኛ መቀመጫ ያለው ፓርቲ መሪ፤ አስቀድሞ የተስማሙበት እጩ፤ ከፈራሚዎቹ ከፍተኛ አስገዳጅ ምክረ ሐሳብ ያገኘ እጩ፤ ወይም አስቀድሞ የታተመ ሌላ ቀመር። አሠራሩ በሕጋዊ እክል፣ በፈቃደኝነት ራስን በማግለል፣ በሞት ወይም በከባድ ሕመም ጊዜ እጩን የመተካት ሂደት መያዝ አለበት።', NULL, NULL, NULL);
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (12, 1, 2, 1, 'coalition');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (12, 'he', 'פרוטוקול סיכון אחוז החסימה', 'אחוז החסימה הקיים הוא 3.25% מהקולות הכשרים. החותמים מתחייבים לפרסם עד המועד האחרון להגשת הרשימות פרוטוקול משותף למפלגות הנמצאות באופן יציב סביב אחוז החסימה או מתחתיו. הפרוטוקול חייב לקבוע מראש: אילו סקרים ציבוריים נלקחים בחשבון; לאיזו תקופה; כיצד מחושב הממוצע; איזה טווח טעות משמש; מי מקבל את ההחלטה; ואילו חלופות נשקלות. הפלטפורמה אינה קובעת אוטומטית איזו מפלגה חייבת לפרוש ואינה מכריזה על קולות עבורה כאבודים לפני התוצאות הרשמיות.', NULL, NULL, NULL),
  (12, 'ar', 'بروتوكول خطر نسبة الحسم', 'نسبة الحسم القائمة هي 3.25% من الأصوات الصحيحة. يلتزم الموقّعون بأن ينشروا قبل الموعد النهائي لتقديم القوائم بروتوكولاً مشتركاً للأحزاب المستقرة قرب نسبة الحسم أو دونها. ويجب أن يحدد البروتوكول سلفاً: أي استطلاعات عامة تُعتمد؛ ولأي فترة؛ وكيف يُحسب المتوسط؛ وأي هامش خطأ يُستخدم؛ ومن يتخذ القرار؛ وأي بدائل تُدرس. لا تحدد المنصة تلقائياً أي حزب يجب أن ينسحب، ولا تعلن الأصوات الممنوحة له ضائعة قبل النتائج الرسمية.', NULL, NULL, NULL),
  (12, 'yi', 'פּראָטאָקאָל פֿונעם ריזיקאָ נישט דורכצוגיין דעם שוועל', 'דער איצטיקער וואַל־שוועל איז 3.25% פֿון די כּשרע שטימען. די אונטערשרײַבער פֿאַרפֿליכטן זיך ביזן לעצטן טערמין פֿון אײַנגעבן די רשימות צו פֿאַרעפֿנטלעכן אַ געמיינזאַמען פּראָטאָקאָל פֿאַר פּאַרטייען וואָס געפֿינען זיך שטענדיק לעבן אָדער אונטערן שוועל. דער פּראָטאָקאָל מוז פֿריִער באַשטימען: וועלכע עפֿנטלעכע אַנקעטן ווערן גערעכנט; פֿאַר וועלכן פּעריאָד; ווי אַזוי מען רעכנט דעם דורכשניט; וועלכער טעות־שפּיל; ווער נעמט אָן דעם באַשלוס; און וועלכע וואַריאַנטן ווערן באַטראַכט.', NULL, NULL, NULL),
  (12, 'ru', 'Протокол риска непрохождения барьера', 'Действующий электоральный барьер составляет 3,25% действительных голосов. Подписанты обязуются до крайнего срока подачи списков опубликовать совместный протокол для партий, устойчиво находящихся вблизи или ниже действующего барьера. Протокол должен заранее определить: какие публичные опросы учитываются; за какой период; как рассчитывается среднее; какой запас погрешности используется; кто принимает решение; какие варианты рассматриваются — совместный список, объединение, отказ от участия либо самостоятельное участие с публичным обоснованием. Платформа не определяет автоматически, какая партия обязана сняться, и не объявляет голоса за неё «потерянными» до официальных результатов.', NULL, NULL, NULL),
  (12, 'en', 'A protocol for the electoral-threshold risk', 'The current electoral threshold is 3.25% of valid votes. Signatories undertake to publish, before the deadline for submitting lists, a joint protocol for parties consistently at or below the threshold. The protocol must determine in advance: which public polls count; over what period; how the average is calculated; what margin of error is used; who decides; and which options are on the table — a joint list, a merger, withdrawal, or running separately with a published justification. The platform does not automatically determine which party must withdraw, and does not declare votes for it lost before the official results.', NULL, NULL, NULL),
  (12, 'am', 'የምርጫ ጣሪያ ስጋት ፕሮቶኮል', 'ነባሩ የምርጫ ጣሪያ ከትክክለኛ ድምፆች 3.25% ነው። ፈራሚዎቹ ዝርዝሮች የሚቀርቡበት የመጨረሻ ቀን ከመድረሱ በፊት፣ ከጣሪያው አካባቢ ወይም በታች በተረጋጋ ሁኔታ ላሉ ፓርቲዎች የጋራ ፕሮቶኮል ለማተም ቃል ይገባሉ። ፕሮቶኮሉ አስቀድሞ መወሰን አለበት፦ የትኞቹ የሕዝብ አስተያየቶች እንደሚታሰቡ፤ ለየትኛው ጊዜ፤ አማካዩ እንዴት እንደሚሰላ፤ የትኛው የስህተት ልዩነት እንደሚውል፤ ውሳኔውን ማን እንደሚሰጥ፤ የትኞቹ አማራጮች እንደሚታዩ።', NULL, NULL, NULL);
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (13, 1, 3, 1, 'coalition');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (13, 'he', 'איסור הסכמים הסותרים את ההסכם שפורסם', 'חותם אינו כורת הסכם סודי המפר את מפת הקואליציה שפורסמה, עוקף את מנגנון המועמד המשותף, מעניק לצד אחר זכות לבטל את ההסכם באופן חד צדדי, או מסתיר חלוקת תפקידים או התחייבויות תקציביות. סודיות תהליך המשא ומתן מותרת. ההתחייבויות הסופיות מתפרסמות לפני ההצבעה על אמון בממשלה.', NULL, NULL, NULL),
  (13, 'ar', 'حظر الاتفاقات المناقضة للاتفاق المنشور', 'لا يبرم الموقّع اتفاقاً سرياً يخالف خريطة الائتلاف المنشورة، أو يلتف على آلية المرشح المشترك، أو يمنح طرفاً آخر حق إلغاء الاتفاق منفرداً، أو يخفي توزيع المناصب أو الالتزامات الميزانية. وتُقبل سرية عملية التفاوض، أما الالتزامات النهائية فتُنشر قبل التصويت على الثقة بالحكومة.', NULL, NULL, NULL),
  (13, 'yi', 'פֿאַרבאָט אויף אָפּמאַכן וואָס ווידערשפּרעכן דעם פֿאַרעפֿנטלעכטן אָפּמאַך', 'אַן אונטערשרײַבער שליסט נישט קיין געהיימען אָפּמאַך וואָס פֿאַרלעצט די פֿאַרעפֿנטלעכטע קאָאַליציע־מאַפּע, אַרומגייט דעם געמיינזאַמען קאַנדידאַט־מעכאַניזם, גיט אַן אַנדער צד דאָס רעכט אַליין אָפּצושאַפֿן דעם אָפּמאַך, אָדער באַהאַלט די פֿאַרטיילונג פֿון שטעלעס אָדער בודזשעט־פֿאַרפֿליכטונגען. די סודותדיקייט פֿונעם פֿאַרהאַנדלונג־פּראָצעס איז דערלויבט. די ענדגילטיקע פֿאַרפֿליכטונגען ווערן פֿאַרעפֿנטלעכט פֿאַר דער שטימונג וועגן צוטרוי צו דער רעגירונג.', NULL, NULL, NULL),
  (13, 'ru', 'Запрет соглашений, противоречащих опубликованному договору', 'Подписант не заключает тайное соглашение, которое нарушает опубликованную карту коалиции, обходит общий механизм кандидата, предоставляет другой стороне право единолично отменить договор или скрывает распределение должностей или бюджетных обязательств. Конфиденциальность переговорного процесса допускается. Итоговые обязательства публикуются до голосования о доверии правительству.', NULL, NULL, NULL),
  (13, 'en', 'No agreements contradicting the published one', 'A signatory does not conclude a secret agreement that breaches the published coalition map, circumvents the shared candidate mechanism, gives another party a unilateral right to cancel the agreement, or conceals the distribution of posts or budget commitments. Confidentiality of the negotiating process is permitted. Final commitments are published before the confidence vote on the government.', NULL, NULL, NULL),
  (13, 'am', 'ከታተመው ስምምነት ጋር የሚቃረኑ ስምምነቶች ክልከላ', 'ፈራሚ የታተመውን የጥምረት ካርታ የሚጥስ፣ የጋራውን የእጩ አሠራር የሚያልፍ፣ ለሌላ ወገን ስምምነቱን በአንድ ወገን የመሻር መብት የሚሰጥ፣ ወይም የቦታዎችን ክፍፍል ወይም የበጀት ቁርጠኝነቶችን የሚደብቅ ሚስጥራዊ ስምምነት አያደርግም። የድርድሩ ሂደት ሚስጥራዊነት ይፈቀዳል። የመጨረሻ ቁርጠኝነቶች በመንግሥት ላይ የመተማመኛ ድምፅ ከመሰጠቱ በፊት ይታተማሉ።', NULL, NULL, NULL);
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (14, 1, 4, 1, 'coalition');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (14, 'he', 'הליך יישוב מחלוקות', 'החותמים קובעים מראש: נציגים למשא ומתן; מועד לבירור מחלוקת; מכלול הנושאים הדורשים הסכמה פה אחד; מכלול הנושאים המוכרעים ברוב; מגשר עצמאי או גוף מוסכם; ואופן ההודעה הפומבית על פרישה מן ההסכם. ההסכם אינו יכול לאפשר למשתתף אחד לחסום את כל הקואליציה בנושא שלא הוכרז מראש כמחייב.', NULL, NULL, NULL),
  (14, 'ar', 'إجراءات حل الخلافات', 'يحدد الموقّعون سلفاً: ممثلين للتفاوض؛ ومهلة للنظر في الخلاف؛ ونطاق المسائل التي تتطلب إجماعاً؛ ونطاق المسائل التي تُحسم بالأغلبية؛ ووسيطاً مستقلاً أو هيئة متفقاً عليها؛ وآلية الإعلان العلني عن الانسحاب من الاتفاق. ولا يجوز أن يسمح الاتفاق لمشارك واحد بتعطيل الائتلاف كله في مسألة لم تُعلن سلفاً ملزمة.', NULL, NULL, NULL),
  (14, 'yi', 'פּראָצעדור פֿון לייזן סיכסוכים', 'די אונטערשרײַבער באַשטימען פֿריִער: פֿאָרשטייער פֿאַר פֿאַרהאַנדלונגען; אַ טערמין פֿאַרן באַטראַכטן אַ סיכסוך; דעם קרײַז פֿראַגן וואָס פֿאָדערן איינשטימיקייט; דעם קרײַז פֿראַגן וואָס ווערן באַשלאָסן מיט אַ מערהייט; אַ זעלבשטענדיקן מיטלער אָדער אַן אָפּגערעדטן אָרגאַן; און דעם סדר פֿון עפֿנטלעך מודיע זײַן וועגן אַרויסגיין פֿונעם אָפּמאַך.', NULL, NULL, NULL),
  (14, 'ru', 'Процедура разрешения споров', 'Подписанты заранее определяют: представителей для переговоров; срок рассмотрения спора; круг вопросов, требующих единогласия; круг вопросов, решаемых большинством; независимого посредника либо согласованный орган; порядок публичного уведомления о выходе из договора. Договор не должен позволять одному участнику блокировать всю коалицию по вопросу, который заранее не был объявлен обязательным.', NULL, NULL, NULL),
  (14, 'en', 'A dispute-resolution procedure', 'Signatories determine in advance: representatives for negotiation; a deadline for considering a dispute; the set of questions requiring unanimity; the set decided by majority; an independent mediator or agreed body; and the procedure for publicly announcing withdrawal from the agreement. The agreement must not let one participant block the whole coalition over a question that was not declared binding in advance.', NULL, NULL, NULL),
  (14, 'am', 'የክርክር መፍቻ ሂደት', 'ፈራሚዎቹ አስቀድመው ይወስናሉ፦ ለድርድር ተወካዮች፤ ክርክር የሚታይበት የጊዜ ገደብ፤ ሙሉ ስምምነት የሚጠይቁ ጉዳዮች፤ በአብላጫ ድምፅ የሚወሰኑ ጉዳዮች፤ ገለልተኛ አስታራቂ ወይም የተስማሙበት አካል፤ ከስምምነቱ ስለመውጣት በይፋ የማሳወቂያ ሥርዓት። ስምምነቱ አንድ ተሳታፊ አስቀድሞ አስገዳጅ ተብሎ ባልተገለጸ ጉዳይ ጥምረቱን በሙሉ እንዲያግድ መፍቀድ የለበትም።', NULL, NULL, NULL);
INSERT INTO demands (id, campaign_id, sort_order, is_active, document) VALUES (15, 1, 5, 1, 'coalition');
INSERT INTO demand_translations (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
  (15, 'he', 'תוכנית משותפת מינימלית', 'החותמים מתחייבים להסכים רק על חבילה מוגבלת: העברת שלטון חוקית; חקירת אירועי 7 באוקטובר; מבנה הממשלה; שקיפות תקציבית; כללי שירות המדינה; צעדי הביטחון והיציבות הכלכלית הראשונים; והליך לדיון בסוגיות אידיאולוגיות שנויות במחלוקת. מחלוקות על הסדר ארוך טווח, שטחים, דת ומודל כלכלי יכולות להישאר, אם נקבע הליך חוקי לקבלת החלטות.', NULL, NULL, NULL),
  (15, 'ar', 'برنامج مشترك بحد أدنى', 'يلتزم الموقّعون بالاتفاق على حزمة محدودة فقط: انتقال السلطة القانوني؛ التحقيق في أحداث السابع من أكتوبر؛ بنية الحكومة؛ شفافية الميزانية؛ قواعد الخدمة المدنية؛ الإجراءات الأولى للأمن والاستقرار الاقتصادي؛ وإجراءات بحث المسائل الأيديولوجية الخلافية. ويمكن أن تبقى الخلافات حول التسوية بعيدة المدى والأراضي والدين والنموذج الاقتصادي، إذا حُدد إجراء قانوني لاتخاذ القرارات.', NULL, NULL, NULL),
  (15, 'yi', 'אַ מינימאַלע געמיינזאַמע פּראָגראַם', 'די אונטערשרײַבער פֿאַרפֿליכטן זיך זיך צו איינציקן בלויז וועגן אַ באַגרענעצטן פּאַקעט: געזעצלעכע איבערגאָב פֿון דער מאַכט; אויספֿאָרשונג פֿון די געשעענישן פֿון 7טן אָקטאָבער; די סטרוקטור פֿון דער רעגירונג; בודזשעט־דורכזיכטיקייט; כּללים פֿון דער מלוכה־דינסט; די ערשטע זיכערהייט־ און עקאָנאָמישע מיטלען; און אַ פּראָצעדור פֿאַר באַהאַנדלען אידעאָלאָגישע מחלוקתן.', NULL, NULL, NULL),
  (15, 'ru', 'Минимальная общая программа', 'Подписанты обязуются согласовать только ограниченный пакет: законная передача власти; расследование событий 7 октября; структура правительства; бюджетная прозрачность; правила государственной службы; первые меры безопасности и экономической устойчивости; процедура рассмотрения спорных идеологических вопросов. Разногласия по долгосрочному урегулированию, территориям, религии и экономической модели могут сохраняться, если определена законная процедура принятия решений.', NULL, NULL, NULL),
  (15, 'en', 'A minimum common programme', 'Signatories undertake to agree on a limited package only: lawful transfer of power; the inquiry into 7 October; the structure of government; budget transparency; civil-service rules; first security and economic-stability measures; and a procedure for handling contested ideological questions. Disagreements over long-term settlement, territory, religion and economic model may remain, provided a lawful decision-making procedure is defined.', NULL, NULL, NULL),
  (15, 'am', 'ዝቅተኛ የጋራ ፕሮግራም', 'ፈራሚዎቹ የተወሰነ ጥቅል ላይ ብቻ ለመስማማት ቃል ይገባሉ፦ ሕጋዊ የሥልጣን ርክክብ፤ የጥቅምት 7 ክስተቶች ምርመራ፤ የመንግሥት መዋቅር፤ የበጀት ግልጽነት፤ የመንግሥት አገልግሎት ደንቦች፤ የመጀመሪያዎቹ የደኅንነትና የኢኮኖሚ መረጋጋት እርምጃዎች፤ አከራካሪ የርዕዮተ ዓለም ጉዳዮችን የማየት ሂደት። በረጅም ጊዜ ስምምነት፣ በግዛቶች፣ በሃይማኖትና በኢኮኖሚ ሞዴል ላይ ልዩነቶች ሊቀጥሉ ይችላሉ፤ ሕጋዊ የውሳኔ አሰጣጥ ሂደት እስከተወሰነ ድረስ።', NULL, NULL, NULL);
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (1, 1, 1, 14, 1);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (1, 'he', 'ועדת חקירה', 'להקים ועדת חקירה ממלכתית לאירועי 7 באוקטובר.', 'החלטת ממשלה לפי חוק ועדות חקירה.', 'הממשלה ומזכיר הממשלה.', 'התקבלה ופורסמה החלטה עם נושא החקירה; נשיא בית המשפט העליון עודכן לצורך מינוי ההרכב.'),
  (1, 'ar', 'لجنة التحقيق', 'تشكيل لجنة تحقيق رسمية في أحداث السابع من أكتوبر.', 'قرار حكومي وفق قانون لجان التحقيق.', 'الحكومة وسكرتير الحكومة.', 'اتُخذ ونُشر قرار يحدد موضوع التحقيق؛ وأُبلغ رئيس المحكمة العليا لتعيين الأعضاء.'),
  (1, 'yi', 'אויספֿאָרשונג־קאָמיסיע', 'שאַפֿן אַ מלוכהשע אויספֿאָרשונג־קאָמיסיע וועגן די געשעענישן פֿון 7טן אָקטאָבער.', 'אַ רעגירונג־באַשלוס לויטן געזעץ וועגן אויספֿאָרשונג־קאָמיסיעס.', 'די רעגירונג און דער סעקרעטאַר פֿון דער רעגירונג.', 'אָנגענומען און פֿאַרעפֿנטלעכט אַ באַשלוס מיטן געגנשטאַנד פֿון דער אויספֿאָרשונג; דער פּרעזידענט פֿונעם העכסטן געריכט איז מודיע געוואָרן.'),
  (1, 'ru', 'Комиссия расследования', 'Создать государственную комиссию расследования событий 7 октября.', 'Решение правительства по Закону о комиссиях расследования.', 'Правительство и секретарь правительства.', 'Принято и опубликовано решение с предметом расследования; уведомлён председатель Верховного суда для назначения состава.'),
  (1, 'en', 'Commission of inquiry', 'Establish a state commission of inquiry into the events of 7 October.', 'Government decision under the Commissions of Inquiry Law.', 'The government and the Cabinet Secretary.', 'A decision setting out the subject of the inquiry is taken and published; the President of the Supreme Court is notified so the members can be appointed.'),
  (1, 'am', 'የምርመራ ኮሚሽን', 'የጥቅምት 7 ክስተቶችን የሚመረምር የመንግሥት ኮሚሽን ማቋቋም።', 'በምርመራ ኮሚሽኖች ሕግ መሠረት የመንግሥት ውሳኔ።', 'መንግሥትና የካቢኔ ጸሐፊ።', 'የምርመራውን ጉዳይ የያዘ ውሳኔ ተሰጥቶ ታትሟል፤ አባላት እንዲሾሙ የጠቅላይ ፍርድ ቤት ፕሬዚዳንት ተነግሮታል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (2, 1, 1, 14, 2);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (2, 'he', 'מבנה הממשלה', 'לאשר ממשלה של 18 שרים לכל היותר וארבעה סגנים.', 'הסכם קואליציוני, החלטות ממשלה ואישורי הכנסת הנדרשים.', 'ראש הממשלה, שר המשפטים, שר האוצר.', 'פורסמו המבנה, הסמכויות ועלות הלשכות.'),
  (2, 'ar', 'بنية الحكومة', 'إقرار حكومة من 18 وزيراً كحد أقصى وأربعة نواب.', 'اتفاق ائتلافي وقرارات حكومية وموافقات الكنيست اللازمة.', 'رئيس الوزراء ووزير القضاء ووزير المالية.', 'نُشرت البنية والصلاحيات وتكلفة الدواوين.'),
  (2, 'yi', 'די סטרוקטור פֿון דער רעגירונג', 'באַשטעטיקן אַ רעגירונג פֿון מאַקסימום 18 מיניסטאָרן און פֿיר וויצע־מיניסטאָרן.', 'אַ קאָאַליציע־אָפּמאַך, רעגירונג־באַשלוסן און די נייטיקע כּנסת־באַשטעטיקונגען.', 'דער פּרעמיער־מיניסטער, דער יוסטיץ־מיניסטער, דער פֿינאַנץ־מיניסטער.', 'פֿאַרעפֿנטלעכט די סטרוקטור, די פֿולמאַכטן און די קאָסטן פֿון די אַפּאַראַטן.'),
  (2, 'ru', 'Структура правительства', 'Утвердить правительство максимум из 18 министров и четырёх заместителей.', 'Коалиционное соглашение, решения правительства и необходимые одобрения Кнессета.', 'Премьер-министр, министр юстиции, министр финансов.', 'Опубликованы структура, полномочия и стоимость аппаратов.'),
  (2, 'en', 'Structure of government', 'Approve a government of at most 18 ministers and four deputies.', 'Coalition agreement, government decisions and the necessary Knesset approvals.', 'The Prime Minister, the Minister of Justice, the Minister of Finance.', 'The structure, powers and cost of ministerial offices are published.'),
  (2, 'am', 'የመንግሥት መዋቅር', 'ቢበዛ 18 ሚኒስትሮችና አራት ምክትሎች ያሉት መንግሥት ማጽደቅ።', 'የጥምረት ስምምነት፣ የመንግሥት ውሳኔዎችና አስፈላጊ የክኔሴት ይሁንታዎች።', 'ጠቅላይ ሚኒስትር፣ የፍትሕ ሚኒስትር፣ የገንዘብ ሚኒስትር።', 'መዋቅሩ፣ ሥልጣኑና የጽሕፈት ቤቶች ወጪ ታትሟል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (3, 1, 1, 21, 3);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (3, 'he', 'פרסום ההתחייבויות הקואליציוניות', 'להקים מרשם ציבורי אחד להסכמים קואליציוניים ולהתחייבויות התקציביות הקשורות.', 'החלטת ממשלה וכללי הקואליציה.', 'מזכיר הממשלה, משרד האוצר.', 'זמינים המסמכים, הנספחים, הסכומים והגופים האחראים.'),
  (3, 'ar', 'نشر الالتزامات الائتلافية', 'إنشاء سجل عام موحد للاتفاقات الائتلافية والالتزامات الميزانية المرتبطة بها.', 'قرار حكومي وقواعد الائتلاف.', 'سكرتير الحكومة ووزارة المالية.', 'الوثائق والملاحق والمبالغ والجهات المسؤولة متاحة.'),
  (3, 'yi', 'פֿאַרעפֿנטלעכן די קאָאַליציע־פֿאַרפֿליכטונגען', 'שאַפֿן איין עפֿנטלעכן רעגיסטער פֿון קאָאַליציע־אָפּמאַכן און פֿאַרבונדענע בודזשעט־פֿאַרפֿליכטונגען.', 'אַ רעגירונג־באַשלוס און קאָאַליציע־כּללים.', 'דער סעקרעטאַר פֿון דער רעגירונג, דאָס פֿינאַנץ־מיניסטעריום.', 'צוטריטלעך זײַנען די דאָקומענטן, בײַלאַגעס, סומעס און פֿאַראַנטוואָרטלעכע אָרגאַנען.'),
  (3, 'ru', 'Публикация коалиционных обязательств', 'Создать единый публичный реестр коалиционных соглашений и связанных бюджетных обязательств.', 'Решение правительства и правила коалиции.', 'Секретарь правительства, Министерство финансов.', 'Доступны документы, приложения, суммы и ответственные органы.'),
  (3, 'en', 'Publishing coalition commitments', 'Create a single public register of coalition agreements and the budget commitments attached to them.', 'Government decision and coalition rules.', 'The Cabinet Secretary, the Ministry of Finance.', 'The documents, annexes, sums and responsible bodies are available.'),
  (3, 'am', 'የጥምረት ቁርጠኝነቶችን ማተም', 'የጥምረት ስምምነቶችንና ተያያዥ የበጀት ቁርጠኝነቶችን የያዘ አንድ ይፋዊ መዝገብ መፍጠር።', 'የመንግሥት ውሳኔና የጥምረት ደንቦች።', 'የካቢኔ ጸሐፊ፣ የገንዘብ ሚኒስቴር።', 'ሰነዶቹ፣ አባሪዎቹ፣ መጠኖቹና ኃላፊ አካላት ተደራሽ ናቸው።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (4, 1, 1, 30, 4);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (4, 'he', 'השתתפות שוויונית בשירות', 'לפרסם הצעת חוק ממשלתית להרחבה הדרגתית של השירות הצבאי, הלאומי או האזרחי עם פטורים אישיים המבוססים על חוק ועל קריטריונים ניתנים לבדיקה.', 'הצעת חוק ממשלתית.', 'משרד הביטחון, משרד המשפטים, משרד האוצר והמשרדים החברתיים.', 'פורסמו יעדי גיוס, מועדים, תמריצים, סנקציות וצורות שירות אזרחי זמינות.'),
  (4, 'ar', 'المشاركة المتساوية في الخدمة', 'نشر مشروع قانون حكومي لتوسيع تدريجي للخدمة العسكرية أو الوطنية أو المدنية مع إعفاءات فردية مستندة إلى القانون ومعايير قابلة للفحص.', 'مشروع قانون حكومي.', 'وزارة الدفاع ووزارة القضاء ووزارة المالية والوزارات الاجتماعية.', 'نُشرت أهداف التجنيد والمواعيد والحوافز والعقوبات وأشكال الخدمة المدنية المتاحة.'),
  (4, 'yi', 'גלײַכע באַטייליקונג אין דינסט', 'פֿאַרעפֿנטלעכן אַ רעגירונג־געזעץ־פֿאָרשלאָג וועגן אַ ביסלעכווײַזער פֿאַרברייטערונג פֿונעם מיליטערישן, נאַציאָנאַלן אָדער ציווילן דינסט מיט אינדיווידועלע אויסנאַמען באַזירט אויף געזעץ.', 'אַ רעגירונג־געזעץ־פֿאָרשלאָג.', 'דאָס פֿאַרטיידיקונג־מיניסטעריום, דאָס יוסטיץ־מיניסטעריום, דאָס פֿינאַנץ־מיניסטעריום און די סאָציאַלע אַמטן.', 'פֿאַרעפֿנטלעכט די רעקרוטירונג־צילן, טערמינען, סטימולן, סאַנקציעס און פֿאָרמען פֿון ציווילן דינסט.'),
  (4, 'ru', 'Равное участие в службе', 'Опубликовать правительственный законопроект о постепенном расширении военной, национальной или гражданской службы с индивидуальными исключениями, основанными на законе и проверяемых критериях.', 'Правительственный законопроект.', 'Министерство обороны, Министерство юстиции, Министерство финансов и социальные ведомства.', 'Опубликованы цели набора, сроки, стимулы, санкции и доступные формы гражданской службы.'),
  (4, 'en', 'Equal participation in service', 'Publish a government bill on gradually broadening military, national or civilian service, with individual exemptions grounded in law and verifiable criteria.', 'Government bill.', 'The Ministry of Defence, Ministry of Justice, Ministry of Finance and the social ministries.', 'Recruitment targets, timelines, incentives, sanctions and the available forms of civilian service are published.'),
  (4, 'am', 'በአገልግሎት እኩል ተሳትፎ', 'በሕግና በሚረጋገጡ መስፈርቶች ላይ የተመሠረቱ የግለሰብ ነጻ መሆኛዎችን ይዞ የወታደራዊ፣ የብሔራዊ ወይም የሲቪል አገልግሎትን ደረጃ በደረጃ ስለማስፋት የመንግሥት ረቂቅ ሕግ ማተም።', 'የመንግሥት ረቂቅ ሕግ።', 'የመከላከያ ሚኒስቴር፣ የፍትሕ ሚኒስቴር፣ የገንዘብ ሚኒስቴርና ማኅበራዊ መሥሪያ ቤቶች።', 'የምልመላ ግቦች፣ የጊዜ ሰሌዳዎች፣ ማበረታቻዎች፣ ቅጣቶችና ተደራሽ የሲቪል አገልግሎት ዓይነቶች ታትመዋል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (5, 1, 1, 30, 5);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (5, 'he', 'כללי עצמאות המשטרה', 'להגדיר את הגבול בין מדיניות כללית של השר לבין התערבות אסורה בחקירות, מחאות ופעולות מבצעיות מסוימות.', 'החלטת ממשלה, הנחיה מחייבת ובמידת הצורך תיקוני חקיקה.', 'השר לביטחון פנים, שר המשפטים, פיקוד המשטרה.', 'פורסמו הכללים ומנגנון להגשת תלונה על התערבות פוליטית.'),
  (5, 'ar', 'قواعد استقلال الشرطة', 'تحديد الحد الفاصل بين السياسة العامة للوزير والتدخل المحظور في تحقيقات واحتجاجات وعمليات بعينها.', 'قرار حكومي وتوجيه ملزم وتعديلات تشريعية عند الحاجة.', 'وزير الأمن الداخلي ووزير القضاء وقيادة الشرطة.', 'نُشرت القواعد وآلية تقديم شكوى بشأن تدخل سياسي.'),
  (5, 'yi', 'כּללים פֿון פּאָליציי־זעלבשטענדיקייט', 'באַשטימען די גרענעץ צווישן דער אַלגעמיינער פּאָליטיק פֿונעם מיניסטער און פֿאַרבאָטענער אַרײַנמישונג אין קאָנקרעטע אויספֿאָרשונגען, פּראָטעסטן און אָפּעראַטיווע מעשׂים.', 'אַ רעגירונג־באַשלוס, אַ מחייבֿדיקע דירעקטיווע און, אויב נייטיק, געזעץ־ענדערונגען.', 'דער מיניסטער פֿון אינערלעכער זיכערהייט, דער יוסטיץ־מיניסטער, די פּאָליציי־פֿירערשאַפֿט.', 'פֿאַרעפֿנטלעכט די כּללים און אַ מעכאַניזם פֿאַר אײַנגעבן אַ קלאָג וועגן פּאָליטישער אַרײַנמישונג.'),
  (5, 'ru', 'Правила независимости полиции', 'Определить границу между общей политикой министра и запрещённым вмешательством в конкретные расследования, протесты и оперативные действия.', 'Решение правительства, обязательная директива и при необходимости законодательные поправки.', 'Министр внутренней безопасности, министр юстиции, руководство полиции.', 'Опубликованы правила и механизм подачи жалобы о политическом вмешательстве.'),
  (5, 'en', 'Rules on police independence', 'Define the boundary between a minister''s general policy and prohibited interference in particular investigations, protests and operations.', 'Government decision, a binding directive and, where needed, legislative amendments.', 'The Minister of Internal Security, the Minister of Justice, the police leadership.', 'The rules and a mechanism for complaining about political interference are published.'),
  (5, 'am', 'የፖሊስ ነጻነት ደንቦች', 'በሚኒስትሩ አጠቃላይ ፖሊሲና በተወሰኑ ምርመራዎች፣ ተቃውሞዎችና ተግባራዊ እርምጃዎች ላይ በተከለከለ ጣልቃ ገብነት መካከል ያለውን ድንበር መወሰን።', 'የመንግሥት ውሳኔ፣ አስገዳጅ መመሪያ እና አስፈላጊ ሲሆን የሕግ ማሻሻያዎች።', 'የውስጥ ደኅንነት ሚኒስትር፣ የፍትሕ ሚኒስትር፣ የፖሊስ አመራር።', 'ደንቦቹና ስለ ፖለቲካ ጣልቃ ገብነት ቅሬታ ማቅረቢያ ሥርዓት ታትመዋል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (6, 1, 1, 45, 6);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (6, 'he', 'ציות להחלטות בית המשפט', 'לאשר פרוטוקול ממלכתי לביצוע פסקי דין סופיים.', 'החלטת ממשלה והנחיה מנהלית.', 'שר המשפטים, היועץ המשפטי לממשלה, מנכ"לי המשרדים.', 'לפסקי דין הדורשים פעולה מנהלית נקבעים גוף אחראי ומועד.'),
  (6, 'ar', 'الامتثال لقرارات المحاكم', 'إقرار بروتوكول حكومي لتنفيذ الأحكام القضائية النهائية.', 'قرار حكومي وتوجيه إداري.', 'وزير القضاء والمستشار القضائي للحكومة ومديرو الوزارات.', 'للأحكام التي تتطلب إجراءً إدارياً تُحدَّد الجهة المسؤولة والمهلة.'),
  (6, 'yi', 'פֿאָלגן די געריכט־באַשלוסן', 'באַשטעטיקן אַ מלוכהשן פּראָטאָקאָל פֿאַרן אויספֿירן ענדגילטיקע געריכט־באַשלוסן.', 'אַ רעגירונג־באַשלוס און אַן אַדמיניסטראַטיווע דירעקטיווע.', 'דער יוסטיץ־מיניסטער, דער יוריסטישער באַראַטער פֿון דער רעגירונג, די פֿירער פֿון די מיניסטעריומס.', 'פֿאַר באַשלוסן וואָס פֿאָדערן אַדמיניסטראַטיווע מעשׂים ווערן פֿעסטגעשטעלט אַ פֿאַראַנטוואָרטלעכער אָרגאַן און אַ טערמין.'),
  (6, 'ru', 'Соблюдение судебных решений', 'Утвердить государственный протокол исполнения окончательных судебных решений.', 'Решение правительства и административная директива.', 'Министр юстиции, юридический советник правительства, руководители министерств.', 'Для решений, требующих административных действий, фиксируются ответственный орган и срок.'),
  (6, 'en', 'Compliance with court rulings', 'Approve a state protocol for carrying out final court rulings.', 'Government decision and an administrative directive.', 'The Minister of Justice, the Attorney General, ministry directors-general.', 'For rulings requiring administrative action, a responsible body and a deadline are recorded.'),
  (6, 'am', 'የፍርድ ቤት ውሳኔዎችን ማክበር', 'የመጨረሻ የፍርድ ውሳኔዎችን ለማስፈጸም የመንግሥት ፕሮቶኮል ማጽደቅ።', 'የመንግሥት ውሳኔና የአስተዳደር መመሪያ።', 'የፍትሕ ሚኒስትር፣ የመንግሥት የሕግ አማካሪ፣ የሚኒስቴር ዋና ዳይሬክተሮች።', 'የአስተዳደር እርምጃ ለሚጠይቁ ውሳኔዎች ኃላፊ አካልና የጊዜ ገደብ ይመዘገባል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (7, 1, 1, 45, 7);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (7, 'he', 'הליך מינוי ראשי גופי הביטחון', 'לפרסם קריטריונים מקצועיים אחידים למינוי ראשי הצבא, המשטרה ושירותי המודיעין.', 'החלטת ממשלה ותיקוני חקיקה במקום שנדרש.', 'ראש הממשלה, שרי הביטחון, המשפטים והביטחון הפנים.', 'פורסמו דרישות ניסיון, בדיקת ניגוד עניינים, משך כהונה ותפקיד הוועדות המקצועיות.'),
  (7, 'ar', 'إجراءات تعيين قادة الأجهزة الأمنية', 'نشر معايير مهنية موحدة لتعيين قادة الجيش والشرطة وأجهزة الاستخبارات.', 'قرار حكومي وتعديلات تشريعية عند اللزوم.', 'رئيس الوزراء ووزراء الدفاع والقضاء والأمن الداخلي.', 'نُشرت متطلبات الخبرة وفحص تضارب المصالح ومدة الولاية ودور اللجان المهنية.'),
  (7, 'yi', 'פּראָצעדור פֿון באַשטימען די פֿירער פֿון די זיכערהייט־אָרגאַנען', 'פֿאַרעפֿנטלעכן איינהייטלעכע פּראָפֿעסיאָנעלע קריטעריעס פֿאַרן באַשטימען די פֿירער פֿון דער אַרמיי, פּאָליציי און די אויסשפּיר־דינסטן.', 'אַ רעגירונג־באַשלוס און געזעץ־ענדערונגען וווּ נייטיק.', 'דער פּרעמיער־מיניסטער, די מיניסטאָרן פֿון פֿאַרטיידיקונג, יוסטיץ און אינערלעכער זיכערהייט.', 'פֿאַרעפֿנטלעכט די פֿאָדערונגען צו דערפֿאַרונג, די קאָנטראָל פֿון אינטערעסן־קאָנפֿליקטן, די קאַדענץ און די ראָלע פֿון די פּראָפֿעסיאָנעלע קאָמיסיעס.'),
  (7, 'ru', 'Процедура назначения руководителей силовых органов', 'Опубликовать единые профессиональные критерии назначения руководителей армии, полиции и разведывательных служб.', 'Решение правительства и законодательные изменения, где они необходимы.', 'Премьер-министр, министры обороны, юстиции и внутренней безопасности.', 'Опубликованы требования к опыту, проверка конфликтов интересов, срок полномочий и роль профессиональных комиссий.'),
  (7, 'en', 'Appointing heads of the security bodies', 'Publish uniform professional criteria for appointing the heads of the army, police and intelligence services.', 'Government decision and legislative changes where required.', 'The Prime Minister and the Ministers of Defence, Justice and Internal Security.', 'Experience requirements, conflict-of-interest screening, term length and the role of professional committees are published.'),
  (7, 'am', 'የደኅንነት አካላት መሪዎችን የመሾም ሂደት', 'የሠራዊት፣ የፖሊስና የስለላ አገልግሎቶች መሪዎችን ለመሾም ወጥ ሙያዊ መስፈርቶችን ማተም።', 'የመንግሥት ውሳኔና አስፈላጊ ሲሆን የሕግ ማሻሻያዎች።', 'ጠቅላይ ሚኒስትር፣ የመከላከያ፣ የፍትሕና የውስጥ ደኅንነት ሚኒስትሮች።', 'የልምድ መስፈርቶች፣ የጥቅም ግጭት ምርመራ፣ የሥልጣን ዘመንና የሙያ ኮሚቴዎች ሚና ታትመዋል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (8, 1, 1, 60, 8);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (8, 'he', 'שקיפות תקציבים נוספים', 'לכלול הוצאות מגזריות נוספות בהליך תקציבי שקוף.', 'כללי תקציב ובמידת הצורך תיקוני חקיקה.', 'משרד האוצר והחשב הכללי.', 'פורסם מרשם של הסכום, מקבל הכספים, המטרה, הקריטריונים ומדדי הבקרה.'),
  (8, 'ar', 'شفافية الميزانيات الإضافية', 'إدراج النفقات القطاعية الإضافية في إجراء ميزاني شفاف.', 'قواعد الميزانية وتعديلات تشريعية عند اللزوم.', 'وزارة المالية والمحاسب العام.', 'نُشر سجل بالمبلغ والمستفيد والغرض والمعايير ومؤشرات الرقابة.'),
  (8, 'yi', 'דורכזיכטיקייט פֿון צוגאָב־בודזשעטן', 'אַרײַננעמען די צוגאָב־סעקטאָר־אויסגאַבן אין אַ דורכזיכטיקן בודזשעט־פּראָצעס.', 'בודזשעט־כּללים און, אויב נייטיק, געזעץ־ענדערונגען.', 'דאָס פֿינאַנץ־מיניסטעריום און דער אַלגעמיינער בוכהאַלטער.', 'פֿאַרעפֿנטלעכט אַ רעגיסטער פֿון דער סומע, דעם באַקומער, דעם ציל, די קריטעריעס און די קאָנטראָל־מאָסן.'),
  (8, 'ru', 'Прозрачность дополнительных бюджетов', 'Включить дополнительные секторальные расходы в прозрачную бюджетную процедуру.', 'Бюджетные правила и при необходимости поправки к законодательству.', 'Министерство финансов и генеральный бухгалтер.', 'Опубликован реестр суммы, получателя, цели, критериев и контрольных показателей.'),
  (8, 'en', 'Transparency of supplementary budgets', 'Bring additional sectoral spending into a transparent budget procedure.', 'Budget rules and, where needed, legislative amendments.', 'The Ministry of Finance and the Accountant General.', 'A register of the amount, recipient, purpose, criteria and control indicators is published.'),
  (8, 'am', 'የተጨማሪ በጀቶች ግልጽነት', 'ተጨማሪ የዘርፍ ወጪዎችን ግልጽ በሆነ የበጀት ሂደት ውስጥ ማካተት።', 'የበጀት ደንቦችና አስፈላጊ ሲሆን የሕግ ማሻሻያዎች።', 'የገንዘብ ሚኒስቴርና ዋና ሒሳብ ሹም።', 'የመጠኑ፣ የተቀባዩ፣ የዓላማው፣ የመስፈርቶቹና የቁጥጥር መለኪያዎች መዝገብ ታትሟል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (9, 1, 1, 60, 9);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (9, 'he', 'תוכנית פיננסית לתקופת המלחמה והשיקום', 'לפרסם תוכנית רב-שנתית להוצאות ביטחון, שיקום אזורים שנפגעו, תמיכה במילואימניקים וייצוב החוב.', 'התקציב ותוכנית פיננסית רב-שנתית.', 'משרד האוצר, משרד הביטחון והמשרדים הכלכליים.', 'פורסמו תרחיש בסיס ותרחיש קיצון, מקורות המימון והסיכונים המרכזיים.'),
  (9, 'ar', 'خطة مالية لفترة الحرب وإعادة الإعمار', 'نشر خطة متعددة السنوات لنفقات الدفاع وإعادة إعمار المناطق المتضررة ودعم جنود الاحتياط وتثبيت الدين.', 'الميزانية وبرنامج مالي متعدد السنوات.', 'وزارة المالية ووزارة الدفاع والوزارات الاقتصادية.', 'نُشر السيناريو الأساسي وسيناريو الضغط ومصادر التمويل والمخاطر الرئيسية.'),
  (9, 'yi', 'אַ פֿינאַנץ־פּלאַן פֿאַר דער מלחמה־ און איבערבוי־תּקופֿה', 'פֿאַרעפֿנטלעכן אַ פֿילִיאָריקן פּלאַן פֿון פֿאַרטיידיקונג־אויסגאַבן, איבערבוי פֿון געליטענע געגנטן, שטיצע פֿאַר רעזערוויסטן און סטאַביליזירן דעם חובֿ.', 'דער בודזשעט און אַ פֿילִיאָריקע פֿינאַנץ־פּראָגראַם.', 'דאָס פֿינאַנץ־מיניסטעריום, דאָס פֿאַרטיידיקונג־מיניסטעריום און די עקאָנאָמישע אַמטן.', 'פֿאַרעפֿנטלעכט אַ באַזיס־ און אַ שטרעס־סצענאַר, די קוואַלן פֿון פֿינאַנצירונג און די הויפּט־ריזיקעס.'),
  (9, 'ru', 'Финансовый план периода войны и восстановления', 'Опубликовать многолетний план оборонных расходов, восстановления пострадавших районов, поддержки резервистов и стабилизации долга.', 'Бюджет и многолетняя финансовая программа.', 'Министерство финансов, Министерство обороны и экономические ведомства.', 'Опубликованы базовый и стрессовый сценарии, источники финансирования и ключевые риски.'),
  (9, 'en', 'A financial plan for war and recovery', 'Publish a multi-year plan for defence spending, reconstruction of affected areas, support for reservists and debt stabilisation.', 'The budget and a multi-year financial programme.', 'The Ministry of Finance, Ministry of Defence and the economic ministries.', 'A baseline and a stress scenario, funding sources and key risks are published.'),
  (9, 'am', 'የጦርነትና የመልሶ ግንባታ ጊዜ የገንዘብ ዕቅድ', 'የመከላከያ ወጪዎችን፣ የተጎዱ አካባቢዎችን መልሶ ግንባታ፣ የተጠባባቂ ወታደሮች ድጋፍና የዕዳ ማረጋጋትን የያዘ የበርካታ ዓመታት ዕቅድ ማተም።', 'በጀትና የበርካታ ዓመታት የገንዘብ ፕሮግራም።', 'የገንዘብ ሚኒስቴር፣ የመከላከያ ሚኒስቴርና የኢኮኖሚ መሥሪያ ቤቶች።', 'መሠረታዊና የጫና ሁኔታዎች፣ የገንዘብ ምንጮችና ዋና ስጋቶች ታትመዋል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (10, 1, 1, 75, 10);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (10, 'he', 'חינוך בסיסי ותעסוקה', 'לקשור מימון ממלכתי של מוסדות חינוך לשקיפות, להוראת ליבה מוסכמת של מקצועות בסיסיים ולתוצאות מדידות.', 'תנאי תקציב, תקנות וחקיקה.', 'משרד החינוך, משרד האוצר, משרד הכלכלה והתעסוקה.', 'פורסמה תוכנית שלבים עם מדדי חינוך ותעסוקה.'),
  (10, 'ar', 'التعليم الأساسي والتشغيل', 'ربط التمويل الحكومي للمؤسسات التعليمية بالشفافية وتدريس نواة متفق عليها من المواد الأساسية ونتائج قابلة للقياس.', 'شروط ميزانية وأنظمة وتشريعات.', 'وزارة التربية ووزارة المالية ووزارة الاقتصاد والعمل.', 'نُشرت خطة مرحلية بمؤشرات التعليم والتشغيل.'),
  (10, 'yi', 'יסודות־בילדונג און באַשעפֿטיקונג', 'פֿאַרבינדן די מלוכה־פֿינאַנצירונג פֿון בילדונג־אַנשטאַלטן מיט דורכזיכטיקייט, מיטן לערנען אַ אָפּגערעדטן קערן פֿון יסוד־פֿאַכן און מיט מעסטלעכע רעזולטאַטן.', 'בודזשעט־באַדינגונגען, תּקנות און געזעצגעבונג.', 'דאָס בילדונג־מיניסטעריום, דאָס פֿינאַנץ־מיניסטעריום, דאָס מיניסטעריום פֿון עקאָנאָמיע און אַרבעט.', 'פֿאַרעפֿנטלעכט אַ עטאַפּן־פּלאַן מיט בילדונג־ און באַשעפֿטיקונג־מאָסן.'),
  (10, 'ru', 'Базовое образование и занятость', 'Связать государственное финансирование образовательных учреждений с прозрачностью, преподаванием согласованного ядра базовых предметов и измеримыми результатами.', 'Бюджетные условия, нормативные акты и законодательство.', 'Министерство образования, Министерство финансов, Министерство экономики и труда.', 'Опубликован поэтапный план с показателями образования и занятости.'),
  (10, 'en', 'Core education and employment', 'Tie state funding of educational institutions to transparency, teaching an agreed core of basic subjects, and measurable outcomes.', 'Budget conditions, regulations and legislation.', 'The Ministry of Education, Ministry of Finance, Ministry of Economy and Labour.', 'A phased plan with education and employment indicators is published.'),
  (10, 'am', 'መሠረታዊ ትምህርትና ሥራ ስምሪት', 'የትምህርት ተቋማት የመንግሥት ገንዘብ ድጋፍን ከግልጽነት፣ ከተስማሙበት መሠረታዊ የትምህርት ዘርፎች ማስተማርና ከሚለኩ ውጤቶች ጋር ማገናኘት።', 'የበጀት ሁኔታዎች፣ ደንቦችና ሕግ።', 'የትምህርት ሚኒስቴር፣ የገንዘብ ሚኒስቴር፣ የኢኮኖሚና ሠራተኛ ሚኒስቴር።', 'የትምህርትና የሥራ ስምሪት መለኪያዎችን የያዘ ደረጃ በደረጃ ዕቅድ ታትሟል።');
INSERT INTO plan_items (id, campaign_id, day_from, day_to, sort_order) VALUES (11, 1, 1, 100, 11);
INSERT INTO plan_item_translations (plan_item_id, locale, title, decision, instrument, owners, criterion) VALUES
  (11, 'he', 'תהליך כללים חוקתיים יציבים', 'להקים תהליך פרלמנטרי-ציבורי בסוגיות הפרדת הרשויות ושינוי חוקי היסוד.', 'החלטת הכנסת ועבודת הוועדה הרלוונטית.', 'יושב ראש הכנסת וועדת החוקה.', 'פורסמו ההרכב, המנדט, לוח הזמנים וכללי ההכרעה ברוב מיוחד.'),
  (11, 'ar', 'عملية قواعد دستورية مستقرة', 'إنشاء عملية برلمانية-مجتمعية في مسائل فصل السلطات وتعديل القوانين الأساسية.', 'قرار الكنيست وعمل اللجنة المختصة.', 'رئيس الكنيست ولجنة الدستور.', 'نُشرت التشكيلة والتفويض والجدول الزمني وقواعد الحسم بأغلبية موسّعة.'),
  (11, 'yi', 'אַ פּראָצעס פֿון שטאַבילע קאָנסטיטוציאָנעלע כּללים', 'שאַפֿן אַ פּאַרלאַמענט־געזעלשאַפֿטלעכן פּראָצעס וועגן די פֿראַגן פֿון טיילן די מאַכטן און ענדערן די יסוד־געזעצן.', 'אַ כּנסת־באַשלוס און די אַרבעט פֿונעם צוגעהעריקן קאָמיטעט.', 'דער פֿאָרזיצער פֿון דער כּנסת און דער קאָנסטיטוציע־קאָמיטעט.', 'פֿאַרעפֿנטלעכט דער צונויפֿשטעל, דער מאַנדאַט, דער צײַטפּלאַן און די כּללים פֿון באַשליסן מיט אַ פֿאַרברייטערטער מערהייט.'),
  (11, 'ru', 'Процесс устойчивых конституционных правил', 'Создать парламентско-общественный процесс по вопросам разделения властей и изменения Основных законов.', 'Решение Кнессета и работа профильного комитета.', 'Председатель Кнессета и Конституционный комитет.', 'Опубликованы состав, мандат, график и правила принятия решений расширенным большинством.'),
  (11, 'en', 'A process for durable constitutional rules', 'Establish a parliamentary and public process on the separation of powers and amendment of the Basic Laws.', 'A Knesset resolution and the work of the relevant committee.', 'The Speaker of the Knesset and the Constitution Committee.', 'The composition, mandate, timetable and supermajority decision rules are published.'),
  (11, 'am', 'ዘላቂ ሕገ መንግሥታዊ ደንቦች ሂደት', 'በሥልጣን ክፍፍልና በመሠረታዊ ሕጎች ማሻሻያ ላይ የፓርላማና የሕዝብ ሂደት ማቋቋም።', 'የክኔሴት ውሳኔና የሚመለከተው ኮሚቴ ሥራ።', 'የክኔሴት አፈ ጉባዔና የሕገ መንግሥት ኮሚቴ።', 'ስብጥሩ፣ ሥልጣኑ፣ የጊዜ ሰሌዳውና በሰፊ አብላጫ ድምፅ የመወሰኛ ደንቦች ታትመዋል።');
INSERT INTO portfolios (id, sort_order) VALUES (1, 1);
INSERT INTO portfolio_translations (portfolio_id, locale, name) VALUES
  (1, 'he', 'ראש הממשלה ותיאום הממשלה'),
