-- Part III to VII of the canonical package: the campaign's real content.
-- Generated from the canonical .docx; ru is authoritative, the other five are
-- machine translations pending human review (see docs/TRANSLATION-REVIEW.md).

ALTER TABLE demands ADD COLUMN document TEXT NOT NULL DEFAULT 'standard';
ALTER TABLE demand_translations ADD COLUMN rationale TEXT;
ALTER TABLE demand_translations ADD COLUMN verification TEXT;
ALTER TABLE demand_translations ADD COLUMN exceptions TEXT;

CREATE TABLE plan_items (
  id INTEGER PRIMARY KEY,
  campaign_id INTEGER NOT NULL REFERENCES campaigns(id),
  day_from INTEGER NOT NULL,
  day_to INTEGER NOT NULL CHECK (day_to >= day_from),
  sort_order INTEGER NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE plan_item_translations (
  plan_item_id INTEGER NOT NULL REFERENCES plan_items(id) ON DELETE CASCADE,
  locale TEXT NOT NULL CHECK (locale IN ('he','ar','yi','ru','en','am')),
  title TEXT NOT NULL,
  decision TEXT NOT NULL,
  instrument TEXT NOT NULL,
  owners TEXT NOT NULL,
  criterion TEXT NOT NULL,
  PRIMARY KEY (plan_item_id, locale)
);
CREATE TABLE portfolios (
  id INTEGER PRIMARY KEY,
  sort_order INTEGER NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE portfolio_translations (
  portfolio_id INTEGER NOT NULL REFERENCES portfolios(id) ON DELETE CASCADE,
  locale TEXT NOT NULL CHECK (locale IN ('he','ar','yi','ru','en','am')),
  name TEXT NOT NULL,
  PRIMARY KEY (portfolio_id, locale)
);

